import React, { useCallback, useEffect, useState } from 'react';
import { Card, Button, Table, message, Input } from 'antd';
import { ArrowLeftOutlined, DeleteOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import request from '../utils/request';

const MARKET_OPTIONS = [
  { value: 'US', label: '美股' },
  { value: 'HK', label: '港股' },
  { value: 'HKNewStock', label: '香港新股' },
  { value: 'CN', label: 'A股' },
  { value: 'SG', label: '新加坡' },
  { value: 'JP', label: '日股' },
  { value: 'Crypto', label: '加密货币' },
  { value: 'FX', label: '外汇' },
];
const DEFAULT_MARKET = 'HKNewStock';

function HkNewStockSupport() {
  const navigate = useNavigate();
  const [stocks, setStocks] = useState([]);
  const [submitting, setSubmitting] = useState(false);
  const [chineseName, setChineseName] = useState('');
  const [underlyingSymbol, setUnderlyingSymbol] = useState('');
  const [market, setMarket] = useState(DEFAULT_MARKET);

  const fetchStocks = useCallback(async () => {
    const res = await request('/api/root/hk-new-stocks', { method: 'GET' });
    if (res?.code === 200 && Array.isArray(res.data)) setStocks(res.data);
  }, []);

  useEffect(() => {
    fetchStocks();
  }, [fetchStocks]);

  const handleAdd = async () => {
    if (!chineseName || !underlyingSymbol) {
      message.warning('请填写完整信息');
      return;
    }
    setSubmitting(true);
    try {
      const res = await request('/api/root/hk-new-stocks', {
        method: 'POST',
        body: JSON.stringify({
          chinese_name: chineseName,
          underlying_symbol: String(underlyingSymbol).trim(),
          market: market || DEFAULT_MARKET,
        }),
      });
      if (res.code === 200) {
        message.success(res.message || '添加成功');
        setChineseName('');
        setUnderlyingSymbol('');
        await fetchStocks();
      } else {
        message.error(res.message || '添加失败');
      }
    } catch (e) {
      message.error('添加失败');
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (symbol) => {
    try {
      const res = await request(`/api/root/hk-new-stocks/${encodeURIComponent(symbol)}`, { method: 'DELETE' });
      if (res.code === 200) {
        message.success('已删除');
        await fetchStocks();
      } else {
        message.error(res.message || '删除失败');
      }
    } catch (e) {
      message.error('删除失败');
    }
  };

  return (
    <div className="equation-tab-page">
      <Card style={{ margin: '16px', marginBottom: 16 }}>
        <Button type="text" icon={<ArrowLeftOutlined />} onClick={() => navigate('/new-stock')}>
          返回新股发行
        </Button>
      </Card>

      <Card style={{ margin: '16px', marginBottom: 16 }} title="添加支持股票">
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginBottom: 12 }}>
          <Input placeholder="ChineseName" value={chineseName} onChange={(e) => setChineseName(e.target.value)} style={{ width: 160 }} />
          <Input placeholder="UnderlyingSymbol" maxLength={6} value={underlyingSymbol} onChange={(e) => setUnderlyingSymbol(e.target.value)} style={{ width: 140 }} />
          <select value={market} onChange={(e) => setMarket(e.target.value)} style={{ width: 140, height: 32 }}>
            {MARKET_OPTIONS.map((o) => (
              <option key={o.value} value={o.value}>{o.label}</option>
            ))}
          </select>
          <Button type="primary" onClick={handleAdd} loading={submitting}>添加</Button>
        </div>
        {stocks.length > 0 && (
          <Table
            className="root-hk-new-stocks-table"
            size="small"
            rowKey="symbol"
            pagination={false}
            dataSource={stocks}
            columns={[
              { title: 'Symbol', dataIndex: 'symbol', key: 'symbol' },
              { title: '市场', dataIndex: 'market', key: 'market', render: (v) => MARKET_OPTIONS.find((o) => o.value === v)?.label ?? v },
              { title: 'ChineseName', dataIndex: 'chinese_name', key: 'chinese_name' },
              { title: 'UnderlyingSymbol', dataIndex: 'underlying_symbol', key: 'underlying_symbol' },
              {
                title: '',
                key: 'action',
                width: 88,
                render: (_, record) => (
                  <Button type="link" danger size="small" icon={<DeleteOutlined />} onClick={() => handleDelete(record.symbol)}>
                    删除
                  </Button>
                ),
              },
            ]}
          />
        )}
      </Card>
    </div>
  );
}

export default HkNewStockSupport;
