import React, { useState, useEffect } from 'react';
import { Form, Input, Button, Card, message, Modal } from 'antd';
import { UserOutlined, LockOutlined, ArrowLeftOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import CryptoJS from 'crypto-js';
import request from '../utils/request';
import { getOrCreateDeviceId } from '../utils/deviceId';

const isUnknownLabel = (value) => {
  if (!value || typeof value !== 'string') return true;
  return value.includes('未知');
};

// 仅展示可识别的被踢设备；全「未知*」时不弹窗（后端也应过滤，此处兜底）
const filterKnownKickedDevices = (kickedDevices) => {
  if (!Array.isArray(kickedDevices)) return [];
  return kickedDevices.filter(
    (d) => d && !isUnknownLabel(d.device) && !isUnknownLabel(d.os) && !isUnknownLabel(d.browser)
  );
};

const formatKickedDeviceLines = (device) => {
  if (!device) return [];
  return [
    `设备：${device.device}`,
    `操作系统：${device.os}`,
    `浏览器：${device.browser}`,
    device.location ? `所在地：${device.location}` : null,
    device.ip ? `IP：${device.ip}` : null,
    device.login_at ? `登录时间：${device.login_at}` : null,
    device.user_agent ? `User-Agent：${device.user_agent}` : null,
  ].filter(Boolean);
};

const showKickedDevicesModal = (kickedDevices) => {
  const known = filterKnownKickedDevices(kickedDevices);
  if (known.length === 0) {
    return;
  }
  Modal.info({
    title: '已将最早登录的设备下线',
    width: 520,
    okText: '知道了',
    content: (
      <div>
        <p style={{ marginBottom: 12 }}>
          同一账号最多同时登录 2 台设备，以下设备已被踢下线：
        </p>
        {known.map((device, index) => (
          <div
            key={index}
            style={{
              marginBottom: index === known.length - 1 ? 0 : 12,
              padding: '10px 12px',
              background: '#f5f5f7',
              borderRadius: 8,
              fontSize: 13,
              lineHeight: 1.7,
              wordBreak: 'break-all',
            }}
          >
            {formatKickedDeviceLines(device).map((line) => (
              <div key={line}>{line}</div>
            ))}
          </div>
        ))}
      </div>
    ),
  });
};

const Login = () => {
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  // Cloud Agent / 本地联调：#/login?agent_test=1&user_id=100002001
  // 仅 localhost；后端须 AGENT_TEST_MODE=1，否则 mint 返回 404。
  useEffect(() => {
    const host = window.location.hostname;
    const isLocal =
      host === 'localhost' || host === '127.0.0.1' || host === '[::1]';
    if (!isLocal) {
      return;
    }
    const q = new URLSearchParams(window.location.hash.split('?')[1] || '');
    if (q.get('agent_test') !== '1') {
      return;
    }
    const userId = Number(q.get('user_id') || '100002001');
    if (!Number.isFinite(userId) || userId <= 0) {
      return;
    }
    let cancelled = false;
    (async () => {
      try {
        setLoading(true);
        const data = await request('/api/auth/agent-test/mint', {
          method: 'POST',
          body: JSON.stringify({ user_id: userId }),
        });
        if (cancelled) return;
        if (data?.code === 200 && data?.data?.token) {
          localStorage.setItem('token', data.data.token);
          message.success(`测试登录 user_id=${userId}`);
          navigate('/');
          return;
        }
        message.error(data?.message || '测试登录失败（后端需 AGENT_TEST_MODE=1）');
      } catch (e) {
        if (!cancelled && (!e || !e.message)) {
          message.error('测试登录失败');
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [navigate]);

  // 检查是否已登录（agent_test 联调走 mint，不在此短路）
  useEffect(() => {
    const q = new URLSearchParams(window.location.hash.split('?')[1] || '');
    if (q.get('agent_test') === '1') {
      return;
    }
    const token = localStorage.getItem('token');
    if (token) {
      console.log('Found existing token, redirecting to home');
      navigate('/');
    }
  }, [navigate]);

  const onFinish = async (values) => {
    try {
      setLoading(true);
      console.log('Login attempt for user:', values.username);
      
      // 使用SHA256加密密码
      const encryptedPassword = CryptoJS.SHA256(values.password).toString();
      console.log('Password encrypted');
      
      const requestData = {
        username: values.username,
        password: encryptedPassword,
        device_id: getOrCreateDeviceId(),
      };
      console.log('Sending login request with data:', { ...requestData, password: '***' });

      const data = await request('/api/auth/login', {
        method: 'POST',
        body: JSON.stringify(requestData),
      });

      console.log('Login response:', data);

      if (data.code === 200 && data.data && data.data.token) {
        // 保存token到localStorage
        const token = data.data.token;
        console.log('Storing token:', token);
        localStorage.setItem('token', token);
        const knownKicked = filterKnownKickedDevices(data.data.kicked_devices);
        if (knownKicked.length > 0) {
          message.success(data.message || '登录成功，已将最早登录的设备下线');
          showKickedDevicesModal(knownKicked);
        } else {
          message.success(data.message || '登录成功');
        }
        navigate('/');
      } else {
        console.error('Invalid login response:', data);
        message.error(data.message || '登录失败');
      }
    } catch (error) {
      console.error('Login error:', error);
      // request 已 toast 过业务错误；仅对未带文案的异常补一条
      if (!error || !error.message) {
        message.error('登录失败，请稍后重试');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ 
      minHeight: '100vh',
      background: '#F2F2F7',
      padding: '24px 16px',
      position: 'relative'
    }}>
      <div style={{ 
        position: 'absolute', 
        top: '24px', 
        left: '16px',
        zIndex: 1000
      }}>
        <button
          onClick={() => navigate('/subscribe-stock')}
          style={{
            background: 'transparent',
            border: 'none',
            padding: '8px',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            gap: '4px',
            color: '#007AFF',
            fontSize: '15px',
            fontWeight: 500,
          }}
        >
          <ArrowLeftOutlined />
          <span>返回</span>
        </button>
      </div>

      <div style={{ 
        maxWidth: '400px',
        margin: '0 auto',
        paddingTop: '60px'
      }}>
        <Card
          title={
            <div style={{ textAlign: 'center', fontSize: '22px', fontWeight: 600 }}>
              登录
            </div>
          }
          bordered={false}
          style={{
            boxShadow: '0 2px 12px rgba(0,0,0,0.08)',
            borderRadius: '16px'
          }}
        >
          <Form
            name="login"
            onFinish={onFinish}
            autoComplete="off"
            layout="vertical"
            size="large"
          >
            <Form.Item
              name="username"
              rules={[{ required: true, message: '请输入用户名' }]}
            >
              <Input
                prefix={<UserOutlined />}
                placeholder="用户名"
              />
            </Form.Item>

            <Form.Item
              name="password"
              rules={[{ required: true, message: '请输入密码' }]}
            >
              <Input.Password
                prefix={<LockOutlined />}
                placeholder="密码"
              />
            </Form.Item>

            <Form.Item>
              <Button
                type="primary"
                htmlType="submit"
                loading={loading}
                style={{
                  width: '100%',
                  height: '44px',
                  borderRadius: '12px',
                  fontSize: '16px',
                  fontWeight: 600,
                }}
              >
                登录
              </Button>
            </Form.Item>
          </Form>
        </Card>
      </div>
    </div>
  );
};

export default Login; 