import React, { useRef, useEffect } from 'react';

// 期权快照通常每天早/下午各一条，日期不连续：按日分槽画短横线，不做 OHLC 柱。
// 并用本合约模拟成交价点连成折线（早盘/午盘各一条），不引用标的融资利率。
const POINT_COLORS = ['#1677ff', '#fa8c16']; // 当日第 1/2 条；第 3+ 条复用末色

const KLineChart = ({ data, width = 800, height = 400 }) => {
  const canvasRef = useRef(null);

  useEffect(() => {
    if (!data || data.length === 0) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;

    canvas.width = width * dpr;
    canvas.height = height * dpr;
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const padding = { top: 28, right: 60, bottom: 40, left: 60 };
    const chartWidth = width - padding.left - padding.right;
    const chartHeight = height - padding.top - padding.bottom;

    ctx.fillStyle = '#fff';
    ctx.fillRect(0, 0, width, height);

    const prices = data.flatMap((d) => (d.points || []).map((p) => p.price));
    if (prices.length === 0) return;

    const minPrice = Math.min(...prices) * 0.995;
    const maxPrice = Math.max(...prices) * 1.005;
    const priceRange = maxPrice - minPrice || 1;

    ctx.strokeStyle = '#e8e8e8';
    ctx.lineWidth = 0.5;
    ctx.fillStyle = '#666';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'left';

    const gridLines = 5;
    for (let i = 0; i <= gridLines; i++) {
      const y = padding.top + (chartHeight / gridLines) * i;
      ctx.beginPath();
      ctx.moveTo(padding.left, y);
      ctx.lineTo(width - padding.right, y);
      ctx.stroke();

      const price = maxPrice - (priceRange / gridLines) * i;
      ctx.fillText(`$${price.toFixed(2)}`, width - padding.right + 5, y + 4);
    }

    const gap = chartWidth / data.length;
    const lineWidth = Math.max(10, Math.min(36, gap * 0.55));
    const labelStep = Math.max(1, Math.ceil(data.length / 8));

    // 按「当日第 N 条快照」分系列收集点，用于本合约成交价折线
    const seriesPoints = [[], []]; // 0=早盘, 1=午盘
    data.forEach((d, i) => {
      const slotCenter = padding.left + gap * i + gap / 2;
      const points = d.points || [];
      points.forEach((p, pi) => {
        if (p.price == null || Number.isNaN(p.price)) return;
        const seriesIdx = Math.min(pi, seriesPoints.length - 1);
        const y = padding.top + ((maxPrice - p.price) / priceRange) * chartHeight;
        seriesPoints[seriesIdx].push({ x: slotCenter, y });
      });
    });

    // 折线先画（在横线下方）
    seriesPoints.forEach((pts, si) => {
      if (pts.length < 2) return;
      ctx.strokeStyle = POINT_COLORS[si];
      ctx.lineWidth = 1.5;
      ctx.globalAlpha = 0.65;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.beginPath();
      ctx.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < pts.length; i++) {
        ctx.lineTo(pts[i].x, pts[i].y);
      }
      ctx.stroke();
      ctx.globalAlpha = 1;
    });

    data.forEach((d, i) => {
      const slotCenter = padding.left + gap * i + gap / 2;
      const points = d.points || [];

      points.forEach((p, pi) => {
        const y = padding.top + ((maxPrice - p.price) / priceRange) * chartHeight;
        const color = POINT_COLORS[Math.min(pi, POINT_COLORS.length - 1)];
        // 同日多条横线略微左右错开，避免完全重叠时看不清
        const offset = (pi - (points.length - 1) / 2) * Math.min(6, lineWidth * 0.15);
        const x0 = slotCenter - lineWidth / 2 + offset;
        const x1 = slotCenter + lineWidth / 2 + offset;

        ctx.strokeStyle = color;
        ctx.lineWidth = 2.5;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(x0, y);
        ctx.lineTo(x1, y);
        ctx.stroke();
      });

      if (i % labelStep === 0) {
        ctx.fillStyle = '#666';
        ctx.font = '10px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText((d.date || '').slice(5), slotCenter, height - padding.bottom + 16);
      }
    });

    // 图例（不在画布再画总标题，避免与 Card title 重复；见 #272）
    const legendY = 16;
    let legendX = padding.left;
    [
      { label: '早盘', color: POINT_COLORS[0] },
      { label: '午盘', color: POINT_COLORS[1] },
    ].forEach((item) => {
      ctx.strokeStyle = item.color;
      ctx.lineWidth = 2.5;
      ctx.beginPath();
      ctx.moveTo(legendX, legendY - 3);
      ctx.lineTo(legendX + 16, legendY - 3);
      ctx.stroke();
      ctx.fillStyle = '#666';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'left';
      ctx.fillText(item.label, legendX + 20, legendY);
      legendX += 56;
    });
  }, [data, width, height]);

  if (!data || data.length === 0) {
    return <div style={{ textAlign: 'center', padding: 40, color: '#999' }}>暂无价格快照数据</div>;
  }

  return (
    <canvas
      ref={canvasRef}
      style={{ display: 'block', margin: '0 auto' }}
    />
  );
};

export default KLineChart;
