import React, { useState, useEffect, useCallback } from 'react';
import { Card, Table, Select, DatePicker, Button, Tag, message, Spin, Empty, Space, Input } from 'antd';
import { useParams, useNavigate } from 'react-router-dom';
import dayjs from 'dayjs';
import request from '../utils/request';
import FundingRateChart from '../components/FundingRateChart';

const { Option } = Select;
const { RangePicker } = DatePicker;
const PAGE_SIZE = 30;

function OptionHistory() {
  const { symbol } = useParams();
  const navigate = useNavigate();

  const [loading, setLoading] = useState(false);
  const [list, setList] = useState([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [putCall, setPutCall] = useState('ALL');
  const [dateRange, setDateRange] = useState(null);
  const [strikes, setStrikes] = useState([]);
  const [expiries, setExpiries] = useState([]);
  const [snapshotDates, setSnapshotDates] = useState([]);
  const [strikePrice, setStrikePrice] = useState(null);
  const [expiryDate, setExpiryDate] = useState(null);
  const [snapshotDate, setSnapshotDate] = useState(null);
  const [fundingRateData, setFundingRateData] = useState([]);
  const [chartStartDate, setChartStartDate] = useState(() => {
    const d = new Date();
    d.setDate(d.getDate() - 21);
    return d.toISOString().split('T')[0];
  });
  const [chartRange, setChartRange] = useState({ start: '', end: '' });

  const loadOptionHistory = useCallback(async (pageNum = 1) => {
    if (!symbol) return;

    try {
      setLoading(true);
      const params = new URLSearchParams();
      params.append('put_call', putCall);
      params.append('page', String(pageNum));
      params.append('page_size', String(PAGE_SIZE));

      if (dateRange && dateRange[0] && dateRange[1]) {
        params.append('start_date', dateRange[0].format('YYYY-MM-DD'));
        params.append('end_date', dateRange[1].format('YYYY-MM-DD'));
      }
      if (strikePrice !== null && strikePrice !== undefined) {
        params.append('strike_price', strikePrice.toString());
      }
      if (expiryDate !== null && expiryDate !== undefined) {
        params.append('expiry_date', expiryDate);
      }
      if (snapshotDate !== null && snapshotDate !== undefined) {
        params.append('snapshot_date', snapshotDate);
      }

      const response = await request(`/api/option-rate/history/${symbol}?${params.toString()}`);
      if (response.code === 200 && response.data) {
        setList(response.data.list || []);
        setTotal(Number(response.data.total) || 0);
        setPage(Number(response.data.page) > 0 ? Number(response.data.page) : pageNum);
        setStrikes(response.data.strikes || []);
        setExpiries(response.data.expiries || []);
        setSnapshotDates(response.data.snapshot_dates || []);
      } else {
        message.error(response.message || '获取期权历史数据失败');
        setList([]);
        setTotal(0);
        setStrikes([]);
        setExpiries([]);
        setSnapshotDates([]);
      }
    } catch (error) {
      console.error('加载期权历史数据失败:', error);
      message.error('加载期权历史数据失败');
      setList([]);
      setTotal(0);
      setStrikes([]);
      setExpiries([]);
      setSnapshotDates([]);
    } finally {
      setLoading(false);
    }
  }, [symbol, putCall, dateRange, strikePrice, expiryDate, snapshotDate]);

  useEffect(() => {
    setPage(1);
    loadOptionHistory(1);
  }, [loadOptionHistory]);

  // 加载融资利率历史数据（每日横线图用，21 天固定窗口）
  useEffect(() => {
    if (!symbol || !chartStartDate) return;

    let cancelled = false;
    // 切换标的时先清空，避免画布残留上一标的折线
    setFundingRateData([]);
    setChartRange({ start: '', end: '' });

    request(`/api/option-rate/funding-rate-history/${encodeURIComponent(symbol)}?start_date=${chartStartDate}`)
      .then(response => {
        if (cancelled) return;
        if (response.code === 200 && response.data) {
          setFundingRateData(response.data.points || []);
          setChartRange({ start: response.data.start_date, end: response.data.end_date });
        }
      })
      .catch(err => {
        if (!cancelled) console.error('加载融资利率历史失败:', err);
      });

    return () => { cancelled = true; };
  }, [symbol, chartStartDate]);

  const handleReset = () => {
    setPutCall('ALL');
    setDateRange(null);
    setStrikePrice(null);
    setExpiryDate(null);
    setSnapshotDate(null);
    setPage(1);
  };

  const columns = [
    {
      title: '快照日期',
      dataIndex: 'snapshot_date',
      key: 'snapshot_date',
      width: 120,
    },
    {
      title: '期权合约代码',
      dataIndex: 'option_symbol',
      key: 'option_symbol',
      width: 160,
      render: (value) => (
        <a
          href={`#/option-rate/symbol/${value}`}
          onClick={(e) => {
            e.preventDefault();
            navigate(`/option-rate/symbol/${value}`);
          }}
          style={{ color: '#1677ff', cursor: 'pointer' }}
        >
          {value}
        </a>
      ),
    },
    {
      title: '期权类型',
      dataIndex: 'put_call',
      key: 'put_call',
      width: 100,
      render: (value) => (
        <Tag color={value === 'CALL' ? 'green' : 'red'}>
          {value === 'CALL' ? '看涨' : '看跌'}
        </Tag>
      ),
    },
    {
      title: '到期日',
      dataIndex: 'expiry_date',
      key: 'expiry_date',
      width: 120,
    },
    {
      title: '行权价',
      dataIndex: 'strike_price',
      key: 'strike_price',
      width: 110,
      align: 'right',
      render: (value) => value !== undefined && value !== null ? `$${value.toFixed(2)}` : '-',
    },
    {
      title: '最新价',
      dataIndex: 'latest_price',
      key: 'latest_price',
      width: 100,
      align: 'right',
      render: (value) => value !== undefined && value !== null ? `$${value.toFixed(2)}` : '-',
    },
    {
      title: '买价',
      dataIndex: 'bid_price',
      key: 'bid_price',
      width: 100,
      align: 'right',
      render: (value) => value !== undefined && value !== null ? `$${value.toFixed(2)}` : '-',
    },
    {
      title: '卖价',
      dataIndex: 'ask_price',
      key: 'ask_price',
      width: 100,
      align: 'right',
      render: (value) => value !== undefined && value !== null ? `$${value.toFixed(2)}` : '-',
    },
    {
      title: '模拟成交价',
      dataIndex: 'sim_fill_price',
      key: 'sim_fill_price',
      width: 110,
      align: 'right',
      render: (value) => value !== undefined && value !== null && value > 0 ? `$${value.toFixed(2)}` : '-',
    },
    {
      title: '持仓量',
      dataIndex: 'open_interest',
      key: 'open_interest',
      width: 100,
      align: 'right',
      render: (value) => value !== undefined && value !== null ? value.toLocaleString() : '-',
    },
    {
      title: '标的现价',
      dataIndex: 'underlying_price',
      key: 'underlying_price',
      width: 110,
      align: 'right',
      render: (value) => value !== undefined && value !== null ? `$${value.toFixed(2)}` : '-',
    },
  ];

  // 当前窗口内有效点（>0）的算术均值，与图表口径一致
  const callRates = fundingRateData.map((d) => d.call_rate).filter((r) => r > 0);
  const putRates = fundingRateData.map((d) => d.put_rate).filter((r) => r > 0);
  const mean = (arr) => (arr.length ? arr.reduce((s, v) => s + v, 0) / arr.length : null);
  const callMean = mean(callRates);
  const putMean = mean(putRates);

  return (
    <div className="equation-tab-page">
      {/* 融资利率历史图表 - 标题左侧放返回按钮 */}
      <Card
        className="equation-table-card"
        title={
          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
            <Button type="link" onClick={() => navigate('/option-rate')} style={{ padding: 0 }}>
              ← 返回
            </Button>
            <span>融资利率历史（每日看涨/看跌融资利率变化）</span>
          </div>
        }
        style={{ marginBottom: 24, borderRadius: '8px', overflow: 'hidden' }}
        styles={{ body: { padding: '12px' } }}
        extra={
          <Space>
            <span style={{ color: '#666', fontSize: '12px' }}>起始日期:</span>
            <DatePicker
              value={chartStartDate ? dayjs(chartStartDate) : null}
              onChange={(date) => {
                if (date && date.format) {
                  setChartStartDate(date.format('YYYY-MM-DD'));
                }
              }}
              format="YYYY-MM-DD"
              allowClear={false}
            />
            <span style={{ color: '#666', fontSize: '12px' }}>结束时间:</span>
            <Input value={chartRange.end || '-'} readOnly style={{ width: 120, color: '#333', backgroundColor: '#f5f5f5', cursor: 'default' }} />
          </Space>
        }
      >
        <FundingRateChart key={symbol} data={fundingRateData} width={760} height={320} />
        {(callMean !== null || putMean !== null) && (
          <div style={{ marginTop: 8, padding: '0 8px', fontSize: 13, color: '#555', display: 'flex', flexWrap: 'wrap', gap: 16 }}>
            <span>
              三周均值 · 看涨：
              <span style={{ color: '#52c41a', fontWeight: 600 }}>
                {callMean !== null ? `${callMean.toFixed(2)}%` : '-'}
              </span>
            </span>
            <span>
              看跌：
              <span style={{ color: '#ff4d4f', fontWeight: 600 }}>
                {putMean !== null ? `${putMean.toFixed(2)}%` : '-'}
              </span>
            </span>
          </div>
        )}
      </Card>

      <Card
        className="equation-table-card"
        title={`${symbol} 期权历史数据`}
        style={{
          marginBottom: 24,
          borderRadius: '8px',
          overflow: 'hidden'
        }}
        styles={{
          body: { padding: '12px' }
        }}
      >
        {/* 筛选器 */}
        <div style={{ marginBottom: 16, display: 'flex', flexWrap: 'wrap', gap: 12, alignItems: 'center' }}>
          <Space>
            <span style={{ color: '#666' }}>快照日期:</span>
            <Select
              value={snapshotDate}
              onChange={setSnapshotDate}
              placeholder="全部"
              style={{ width: 140 }}
              allowClear
            >
              {snapshotDates.map((d) => (
                <Option key={d} value={d}>{d}</Option>
              ))}
            </Select>
          </Space>

          <Space>
            <span style={{ color: '#666' }}>期权类型:</span>
            <Select value={putCall} onChange={setPutCall} style={{ width: 100 }}>
              <Option value="ALL">全部</Option>
              <Option value="CALL">看涨</Option>
              <Option value="PUT">看跌</Option>
            </Select>
          </Space>

          <Space>
            <span style={{ color: '#666' }}>日期范围:</span>
            <RangePicker
              value={dateRange}
              onChange={setDateRange}
              format="YYYY-MM-DD"
              allowClear
            />
          </Space>

          <Space>
            <span style={{ color: '#666' }}>行权价:</span>
            <Select
              value={strikePrice}
              onChange={setStrikePrice}
              placeholder="全部"
              style={{ width: 120 }}
              allowClear
              dropdownMatchSelectWidth={false}
            >
              {strikes.map((s) => (
                <Option key={s} value={s}>${s.toFixed(2)}</Option>
              ))}
            </Select>
          </Space>

          <Space>
            <span style={{ color: '#666' }}>到期日:</span>
            <Select
              value={expiryDate}
              onChange={setExpiryDate}
              placeholder="全部"
              style={{ width: 140 }}
              allowClear
            >
              {expiries.map((e) => (
                <Option key={e} value={e}>{e}</Option>
              ))}
            </Select>
          </Space>

          <Button onClick={handleReset}>重置</Button>
        </div>

        {/* 数据表格 */}
        <Spin spinning={loading}>
          {list.length === 0 && !loading ? (
            <Empty description="暂无期权历史数据" />
          ) : (
            <Table
              columns={columns}
              dataSource={list}
              rowKey={(record) => `${record.id || record.option_symbol}-${record.snapshot_date}-${record.create_at}`}
              pagination={{
                current: page,
                pageSize: PAGE_SIZE,
                total,
                showSizeChanger: false,
                showTotal: (n) => `共 ${n} 条`,
                onChange: (p) => loadOptionHistory(p),
              }}
              scroll={{ x: 'max-content' }}
              size="small"
            />
          )}
        </Spin>

        {total > 0 && (
          <div style={{ marginTop: 12, color: '#8E8E93', fontSize: 12 }}>
            数据来源于定时任务快照，按合约平铺展示，每页 {PAGE_SIZE} 条。
          </div>
        )}
      </Card>
    </div>
  );
}

export default OptionHistory;
