import React, { useState } from 'react';
import { Card, Form, Input, Button, Table, AutoComplete, message } from 'antd';
import { CalculatorOutlined, ArrowLeftOutlined } from '@ant-design/icons';
import { useLocation, useNavigate } from 'react-router-dom';
import request from '../utils/request';

function LowBuyStrategy() {
  const location = useLocation();
  const navigate = useNavigate();
  const isOptionCalculatorDetail = location.pathname.startsWith('/option-calculator/');
  const [form] = Form.useForm();
  const [options, setOptions] = useState([]);
  const [selectedStocks, setSelectedStocks] = useState([]);
  const [loading, setLoading] = useState(false);
  const [strategyResults, setStrategyResults] = useState([]);
  const [calculating, setCalculating] = useState(false);

  const columns = [
    {
      title: '股票名称',
      dataIndex: 'stock_name',
      key: 'stock_name',
      width:90
    },
    {
      title: '当前价格',
      dataIndex: 'stock_current_price',
      key: 'stock_current_price',
      width:90
    },
    {
      title: '期权类型',
      dataIndex: 'put_call',
      key: 'put_call'
    },
    {
      title: '行权价',
      dataIndex: 'strike_price',
      key: 'strike_price',
      width:80
    },
    {
      title: '行权买入成本/最大损失',
      dataIndex: 'max_loss',
      key: 'max_loss',
      width:80
    },
    {
      title: '到期日',
      dataIndex: 'expiry_date',
      key: 'expiry_date',
    },
    {
      title: '固定收益/期权价格',
      dataIndex: 'benefit',
      key: 'benefit',
      width:94,
      render: (text, record) => record.market === 'HK' ? `HK$${text}` : `$${text}`
    },
    {
      title: '年化收益率',
      dataIndex: 'profit_percent',
      key: 'profit_percent',
      render: (text) => `${text.toFixed(2)}%`
    },
  ];

  const handleSearch = async (value) => {
    if (!value) {
      setOptions([]);
      return;
    }

    try {
      setLoading(true);
      console.log('Searching for stock:', value);
      const response = await request('/api/stock/search', {
        method: 'POST',
        body: JSON.stringify({ name: value }),
      });

      console.log('Search response:', response);
      if (response.code === 200 && Array.isArray(response.data)) {
        const stockOptions = response.data.map(stock => ({
          value: stock.symbol,
          label: (
            <div>
              <div>{stock.symbol}</div>
              <div style={{ fontSize: '12px', color: '#8E8E93' }}>{stock.chinese_name}</div>
            </div>
          ),
          stock: stock
        }));
        setOptions(stockOptions);
      } else {
        console.log('Invalid response format:', response);
        setOptions([]);
        message.error('找不到对应的股票:'+value);
      }
    } catch (error) {
      console.error('搜索股票失败:', error);
      message.error('搜索失败，请稍后重试');
      setOptions([]);
    } finally {
      setLoading(false);
    }
  };

  const handleSelect = async (value, option) => {
    const stock = option.stock;
    if (!selectedStocks.some(s => s.symbol === stock.symbol)) {
      setSelectedStocks([...selectedStocks, { 
        ...stock, 
        safe_level_price: ''
      }]);
      
      // 调用预加载接口，预加载看跌期权数据
      try {
        await request('/api/stock/pre-load', {
          method: 'POST',
          body: JSON.stringify({ 
            symbol: stock.symbol,
            put_call: 'PUT'
          })
        });
      } catch (error) {
        console.error('看跌期权数据预加载失败:', error);
        // 预加载失败不影响主流程，所以这里不显示错误提示
      }
    }
  };

  const handleSafeLevelPriceChange = (value, symbol) => {
    setSelectedStocks(stocks => 
      stocks.map(stock => 
        stock.symbol === symbol 
          ? { ...stock, safe_level_price: value }
          : stock
      )
    );
  };

  const handleRemoveStock = (symbol) => {
    setSelectedStocks(stocks => stocks.filter(stock => stock.symbol !== symbol));
  };


  const onFinish = async () => {
    if (selectedStocks.length === 0) {
      message.warning('请至少添加一只股票');
      return;
    }

    const invalidStocks = selectedStocks.filter(stock => !stock.safe_level_price);
    if (invalidStocks.length > 0) {
      message.warning('请为所有股票设置安全价格');
      return;
    }

    try {
      setStrategyResults([]);
      setCalculating(true);

      const timestamp = new Date().getTime();
      const response = await request('/api/put/options/low-buy', {
        method: 'POST',
        body: JSON.stringify({
          stock_list: selectedStocks.map(stock => ({
            symbol: stock.symbol,
            safe_level_price: parseFloat(stock.safe_level_price)
          })),
          timestamp: timestamp
        }),
      });

      if (Array.isArray(response.data)) {
        setStrategyResults(response.data);
      } else {
        message.error('获取策略结果失败');
        setStrategyResults([]);
      }
    } catch (error) {
      console.error('计算策略失败:', error);
      message.error('计算策略失败，请稍后重试');
      setStrategyResults([]);
    } finally {
      setCalculating(false);
    }
  };

  return (
    <div style={{ 
      paddingBottom: 'calc(80px + env(safe-area-inset-bottom, 0px) + 50px)',
      minHeight: '100vh',
      boxSizing: 'border-box',
      paddingLeft: 'env(safe-area-inset-left, 0px)',
      paddingRight: 'env(safe-area-inset-right, 0px)',
      paddingTop: 'env(safe-area-inset-top, 0px)',
      WebkitOverflowScrolling: 'touch',
      overflowX: 'hidden',
      width: '100%',
      position: 'relative'
    }}>
      {isOptionCalculatorDetail && (
        <div style={{ padding: '0 0 8px' }}>
          <Button
            type="text"
            icon={<ArrowLeftOutlined />}
            onClick={() => navigate(-1)}
            style={{
              padding: '4px 8px',
              display: 'flex',
              alignItems: 'center',
              gap: '4px',
              color: 'rgba(0, 0, 0, 0.88)',
            }}
          >
            返回
          </Button>
        </div>
      )}
      <Card 
        title="持有现金，卖出看跌期权策略" 
        style={{ 
          marginBottom: 24,
          borderRadius: '8px',
          overflow: 'hidden'
        }}
        styles={{
          body: {
            padding: '12px'
          }
        }}
      >
        <Form
          form={form}
          layout="vertical"
          onFinish={onFinish}
        >
            <AutoComplete
              options={options}
              onSearch={handleSearch}
              onSelect={handleSelect}
              placeholder="请输入股票代码或名称，来添加股票"
              loading={loading}
              style={{ 
                width: '100%',
                marginBottom: '16px'
              }}
            />
 
          {selectedStocks.length > 0 && (
            <Table
              dataSource={selectedStocks}
              columns={[
                {
                  title: '股票名称',
                  dataIndex: 'chinese_name',
                  key: 'chinese_name',
                  ellipsis: true,
                },
                {
                  title: '股票符号',
                  dataIndex: 'symbol',
                  key: 'symbol',
                  ellipsis: true,
                },
                {
                  title: '安全价格',
                  dataIndex: 'safe_level_price',
                  key: 'safe_level_price',
                  width: 90,
                  align: 'left',
                  render: (_, record) => (
                    <Input
                      type="number"
                      placeholder="请输入"
                      value={record.safe_level_price}
                      onChange={e => handleSafeLevelPriceChange(e.target.value, record.symbol)}
                      style={{ 
                        width: '75px',
                        padding: '1px 2px'
                      }}
                    />
                  ),
                },
                {
                  title: '操作',
                  key: 'action',
                  width: 60,
                  render: (_, record) => (
                    <Button 
                      type="link" 
                      danger 
                      onClick={() => handleRemoveStock(record.symbol)}
                      style={{
                        padding: '4px 8px'
                      }}
                    >
                      删除
                    </Button>
                  ),
                },
              ]}
              rowKey="symbol"
              pagination={false}
              size="small"
              scroll={{ x: 'max-content' }}
              style={{
                marginBottom: '16px'
              }}
            />
          )}

          <Form.Item style={{ marginBottom: 0 }}>
            <Button 
              type="default" 
              htmlType="submit" 
              loading={calculating}
              disabled={selectedStocks.length === 0}
              style={{
                width: '100%',
                height: '40px',
                fontSize: '16px',
                background: 'rgba(255, 255, 255, 0.8)',
                backdropFilter: 'blur(10px)',
                border: '1px solid rgba(0, 0, 0, 0.1)',
                boxShadow: '0 2px 8px rgba(0, 0, 0, 0.05)',
                transition: 'all 0.3s',
                color: '#1C1C1E',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: '8px'
              }}
              className="calculate-button"
              icon={<CalculatorOutlined />}
            >
              期权盈亏计算
            </Button>
          </Form.Item>
        </Form>
      </Card>

      <Card 
        title="策略结果" 
        style={{ 
          borderRadius: '8px',
          overflow: 'hidden'
        }}
        styles={{
          body: {
            padding: '12px'
          }
        }}
      >
        <Table
          columns={columns}
          dataSource={strategyResults}
          rowKey={(record) => `${record.symbol}-${record.strike_price}-${record.expiry_date}`}
          loading={calculating}
          size="small"
          scroll={{ x: 'max-content' }}
        />
      </Card>
    </div>
  );
}

export default LowBuyStrategy; 