import React, { useRef, useEffect } from 'react';

// 融资利率每日图表：横线 + 折线，展示看涨/看跌融资利率每日变化趋势。
// data: [{ date: 'YYYY-MM-DD', call_rate: number, put_rate: number, ... }]
const FundingRateChart = ({ data, width = 800, height = 400 }) => {
  const canvasRef = useRef(null);

  useEffect(() => {
    if (!data || data.length === 0) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;

    canvas.width = width * dpr;
    canvas.height = height * dpr;
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const padding = { top: 36, right: 60, bottom: 56, left: 60 };
    const chartWidth = width - padding.left - padding.right;
    const chartHeight = height - padding.top - padding.bottom;

    ctx.fillStyle = '#fff';
    ctx.fillRect(0, 0, width, height);

    // 计算 Y 轴范围
    const allRates = data.flatMap(d => [d.call_rate, d.put_rate].filter(r => r > 0));
    if (allRates.length === 0) return;

    const minRate = Math.min(...allRates) * 0.9;
    const maxRate = Math.max(...allRates) * 1.1;
    const rateRange = maxRate - minRate || 1;

    // 绘制网格和 Y 轴标签
    const gridLines = 5;
    ctx.strokeStyle = '#e8e8e8';
    ctx.lineWidth = 0.5;
    ctx.fillStyle = '#666';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'right';

    for (let i = 0; i <= gridLines; i++) {
      const y = padding.top + (chartHeight / gridLines) * i;
      ctx.beginPath();
      ctx.moveTo(padding.left, y);
      ctx.lineTo(width - padding.right, y);
      ctx.stroke();

      const rate = maxRate - (rateRange / gridLines) * i;
      ctx.fillText(`${rate.toFixed(1)}%`, padding.left - 8, y + 4);
    }

    // X 轴：按日分槽画横线
    const gap = chartWidth / data.length;
    const lineWidth = Math.max(12, Math.min(32, gap * 0.4));
    const labelStep = Math.max(1, Math.ceil(data.length / 10));

    // 收集有效数据点用于折线
    const callPoints = [];
    const putPoints = [];
    data.forEach((d, i) => {
      const slotCenter = padding.left + gap * i + gap / 2;
      if (d.call_rate > 0) {
        const y = padding.top + ((maxRate - d.call_rate) / rateRange) * chartHeight;
        callPoints.push({ x: slotCenter, y });
      }
      if (d.put_rate > 0) {
        const y = padding.top + ((maxRate - d.put_rate) / rateRange) * chartHeight;
        putPoints.push({ x: slotCenter, y });
      }
    });

    // 看涨融资利率折线（绿色）
    if (callPoints.length > 1) {
      ctx.strokeStyle = '#52c41a';
      ctx.lineWidth = 1.5;
      ctx.globalAlpha = 0.6;
      ctx.beginPath();
      ctx.moveTo(callPoints[0].x, callPoints[0].y);
      for (let i = 1; i < callPoints.length; i++) {
        ctx.lineTo(callPoints[i].x, callPoints[i].y);
      }
      ctx.stroke();
      ctx.globalAlpha = 1;
    }

    // 看跌融资利率折线（红色）
    if (putPoints.length > 1) {
      ctx.strokeStyle = '#ff4d4f';
      ctx.lineWidth = 1.5;
      ctx.globalAlpha = 0.6;
      ctx.beginPath();
      ctx.moveTo(putPoints[0].x, putPoints[0].y);
      for (let i = 1; i < putPoints.length; i++) {
        ctx.lineTo(putPoints[i].x, putPoints[i].y);
      }
      ctx.stroke();
      ctx.globalAlpha = 1;
    }

    // 画每日横线
    data.forEach((d, i) => {
      const slotCenter = padding.left + gap * i + gap / 2;

      // 看涨融资利率横线（绿色）
      if (d.call_rate > 0) {
        const y = padding.top + ((maxRate - d.call_rate) / rateRange) * chartHeight;
        ctx.strokeStyle = '#52c41a';
        ctx.lineWidth = 3;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(slotCenter - lineWidth / 2, y);
        ctx.lineTo(slotCenter + lineWidth / 2 - 2, y);
        ctx.stroke();
      }

      // 看跌融资利率横线（红色）
      if (d.put_rate > 0) {
        const y = padding.top + ((maxRate - d.put_rate) / rateRange) * chartHeight;
        ctx.strokeStyle = '#ff4d4f';
        ctx.lineWidth = 3;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(slotCenter - lineWidth / 2 + 2, y);
        ctx.lineTo(slotCenter + lineWidth / 2, y);
        ctx.stroke();
      }

      // X 轴日期标签
      if (i % labelStep === 0) {
        ctx.fillStyle = '#666';
        ctx.font = '10px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(d.date.slice(5), slotCenter, height - padding.bottom + 18);
      }
    });

    // 图例
    const legendY = 16;
    let legendX = padding.left;

    // 看涨融资利率
    ctx.strokeStyle = '#52c41a';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(legendX, legendY - 3);
    ctx.lineTo(legendX + 16, legendY - 3);
    ctx.stroke();
    ctx.fillStyle = '#333';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('看涨融资利率', legendX + 22, legendY + 1);
    legendX += 110;

    // 看跌融资利率
    ctx.strokeStyle = '#ff4d4f';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(legendX, legendY - 3);
    ctx.lineTo(legendX + 16, legendY - 3);
    ctx.stroke();
    ctx.fillStyle = '#333';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('看跌融资利率', legendX + 22, legendY + 1);

  }, [data, width, height]);

  if (!data || data.length === 0) {
    return <div style={{ textAlign: 'center', padding: 40, color: '#999' }}>暂无融资利率历史数据</div>;
  }

  return (
    <canvas
      ref={canvasRef}
      style={{ display: 'block', margin: '0 auto' }}
    />
  );
};

export default FundingRateChart;
