import React, { useEffect, useMemo, useState } from 'react';
import { Button } from 'antd';
import { ArrowLeftOutlined } from '@ant-design/icons';
import { useNavigate, useSearchParams } from 'react-router-dom';

function DpBestPathDetail() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [iframeHeight, setIframeHeight] = useState('calc(100vh - 120px - env(safe-area-inset-top, 0px))');
  const panelSrc = useMemo(() => {
    const base = (process.env.PUBLIC_URL || '').replace(/\/$/, '');
    const token = localStorage.getItem('token') || '';
    const params = new URLSearchParams({ token });
    const runId = searchParams.get('run_id');
    if (runId) params.set('run_id', runId);
    const page = searchParams.get('page');
    if (page) params.set('page', page);
    return `${base}/dp-best-path-panel.html?${params.toString()}`;
  }, [searchParams]);


  useEffect(() => {
    const handleMessage = (event) => {
      if (event.origin !== window.location.origin) return;
      if (event.data?.type !== 'dp-best-path-panel-height') return;
      const nextHeight = Math.ceil(Number(event.data.height) || 0);
      if (nextHeight > 0) {
        setIframeHeight(`${nextHeight}px`);
      }
    };
    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, []);

  return (
    <div style={{
      display: 'flex',
      flexDirection: 'column',
      boxSizing: 'border-box',
    }}>
      <div style={{
        position: 'sticky',
        top: 0,
        zIndex: 1000,
        background: '#fff',
        padding: '12px 16px',
        borderBottom: '1px solid #E5E5EA',
        display: 'flex',
        alignItems: 'center',
        gap: '12px',
      }}>
        <Button
          type="text"
          icon={<ArrowLeftOutlined />}
          onClick={() => navigate('/fund-temperature/option-buyer-term')}
          style={{ padding: '4px 8px' }}
        >
          返回
        </Button>
        <span style={{ fontSize: '16px', fontWeight: 600 }}>期权备兑最优路径</span>
      </div>
      <iframe
        title="期权备兑最优路径"
        src={panelSrc}
        style={{
          display: 'block',
          width: '100%',
          height: iframeHeight,
          border: 'none',
          background: '#fafafa',
        }}
        scrolling="no"
      />
    </div>
  );
}

export default DpBestPathDetail;
