import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Card, Button, Table } from 'antd';
import { ArrowLeftOutlined, ReloadOutlined } from '@ant-design/icons';
import { useNavigate, useParams, Navigate } from 'react-router-dom';
import { newStockSections } from '../data/newStockSections';
import {
  szChinextAhArbitrageIntro,
  szChinextAhArbitrageColumns,
  szChinextAhFallbackMeta,
  szChinextAhFallbackRows,
  szChinextFilteredFallbackRows,
  szChinextSupportedPairs,
  szChinextDisplayLimit,
} from '../data/szChinextAhData';
import {
  cbondFirstDayMeta,
  cbondFirstDayRows,
  cbondFirstDayColumns,
  cbondUpcomingMeta,
  cbondUpcomingFallbackRows,
  cbondUpcomingColumns,
  buildCbondFirstDayStats,
} from '../data/cbondFirstDayData';
import { fetchCbondFirstDayUpdates, fetchCbondUpcomingCalendar } from '../data/cbondFirstDayLive';
import {
  shStarAhArbitrageIntro,
  shStarAhFallbackMeta,
  shStarAhFallbackRows,
  shStarFilteredFallbackRows,
  shStarSupportedPairs,
  shStarDisplayLimit,
} from '../data/shStarAhData';

const TENCENT_QUOTE_ENDPOINT = 'https://qt.gtimg.cn/q=';
const FX_ENDPOINT = 'https://open.er-api.com/v6/latest/HKD';

const AH_SECTION_CONFIGS = {
  'sh-star': {
    intro: shStarAhArbitrageIntro,
    fallbackMeta: shStarAhFallbackMeta,
    fallbackRows: shStarAhFallbackRows,
    filteredFallbackRows: shStarFilteredFallbackRows,
    pairs: shStarSupportedPairs,
    displayLimit: shStarDisplayLimit,
    aQuotePrefix: 'sh',
    scopeText:
      '仅展示已纳入港交所官方个股期权名单、且同时在沪市主板或科创板有 A 股上市的公司',
    emptyText: '当前没有已纳入港交所官方个股期权名单、且同时在沪市主板或科创板上市的 A/H 公司。',
  },
  'sz-chinext': {
    intro: szChinextAhArbitrageIntro,
    fallbackMeta: szChinextAhFallbackMeta,
    fallbackRows: szChinextAhFallbackRows,
    filteredFallbackRows: szChinextFilteredFallbackRows,
    pairs: szChinextSupportedPairs,
    displayLimit: szChinextDisplayLimit,
    aQuotePrefix: 'sz',
    scopeText:
      '仅展示已纳入港交所官方个股期权名单、且同时在深市主板或创业板有 A 股上市的公司',
    emptyText: '当前没有已纳入港交所官方个股期权名单、且同时在深市主板或创业板上市的 A/H 公司。',
  },
};

const AH_FALLBACK_ROWS_BY_A_CODE = Object.fromEntries(
  Object.entries(AH_SECTION_CONFIGS).map(([key, config]) => [
    key,
    new Map(config.fallbackRows.map((row) => [row.aCode, row])),
  ])
);

const formatShanghaiTimestamp = (date = new Date()) =>
  new Intl.DateTimeFormat('zh-CN', {
    timeZone: 'Asia/Shanghai',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  })
    .format(date)
    .replace(/\//g, '-');

const buildTencentSymbols = (pairs, aQuotePrefix) =>
  pairs.flatMap((pair) => [`${aQuotePrefix}${pair.aCode}`, `hk${pair.hCode}`]);

const parseTencentQuoteText = (rawText) => {
  const quoteMap = new Map();

  rawText
    .split('\n')
    .map((line) => line.trim())
    .forEach((line) => {
      const match = line.match(/^v_([^=]+)="(.*)";$/);
      if (!match) return;

      const [, symbol, payload] = match;
      const fields = payload.split('~');
      const price = Number(fields[3]);

      if (!Number.isFinite(price)) return;

      quoteMap.set(symbol, {
        symbol,
        code: fields[2],
        name: fields[1],
        price,
      });
    });

  return quoteMap;
};

const buildAhRows = ({ pairs, fallbackRowsByACode, quoteMap, fxRate, displayLimit, aQuotePrefix }) => {
  let livePairCount = 0;

  const rows = pairs
    .map((pair) => {
      const fallbackRow = fallbackRowsByACode.get(pair.aCode);
      const aQuote = quoteMap.get(`${aQuotePrefix}${pair.aCode}`);
      const hQuote = quoteMap.get(`hk${pair.hCode}`);
      const hasLivePair = aQuote && hQuote;

      if (hasLivePair) {
        livePairCount += 1;
      }

      const aCny = hasLivePair ? aQuote.price : fallbackRow.aCny;
      const hHkd = hasLivePair ? hQuote.price : fallbackRow.hHkd;
      const hCny = Number((hHkd * fxRate).toFixed(2));
      const diffPct = Number((((hCny - aCny) / aCny) * 100).toFixed(2));

      return {
        key: pair.aCode,
        board: pair.board,
        stockName: pair.stockName,
        aCode: pair.aCode,
        hCode: pair.hCode,
        hHkd,
        hCny,
        aCny,
        diffPct,
      };
    })
    .sort((left, right) => right.diffPct - left.diffPct)
    .slice(0, displayLimit)
    .map((row, index) => ({
      ...row,
      key: row.aCode,
      rank: index + 1,
    }));

  return { rows, livePairCount };
};

const buildInitialAhMeta = (config) => ({
  mode: 'fallback',
  fetchedAt: config.fallbackMeta.snapshotTime,
  fxRate: config.fallbackMeta.fxRate,
  livePairCount: 0,
  totalPairs: config.pairs.length,
  usedFallbackRate: true,
  message: `实时接口不可用时回退到 ${config.fallbackMeta.snapshotLabel}。`,
});

const buildInitialAhSectionState = () =>
  Object.fromEntries(
    Object.entries(AH_SECTION_CONFIGS).map(([key, config]) => [
      key,
      {
        rows: config.filteredFallbackRows,
        loading: false,
        meta: buildInitialAhMeta(config),
      },
    ])
  );

const buildInitialCbondState = () => ({
  rows: cbondFirstDayRows,
  loading: false,
  meta: {
    mode: 'fallback',
    fetchedAt: cbondFirstDayMeta.snapshotLabel,
    rangeStart: cbondFirstDayMeta.rangeStart,
    rangeEnd: cbondFirstDayMeta.rangeEnd,
    source: cbondFirstDayMeta.source,
    message: `当前展示 ${cbondFirstDayMeta.snapshotLabel}，点击右上角可刷新新上市债券。`,
    liveRowCount: 0,
    totalListed: cbondFirstDayRows.length,
  },
});

const buildInitialCbondCalendarState = () => ({
  rows: cbondUpcomingFallbackRows,
  loading: false,
  meta: {
    mode: 'fallback',
    fetchedAt: cbondUpcomingMeta.snapshotLabel,
    source: cbondUpcomingMeta.source,
    message: `当前展示 ${cbondUpcomingMeta.snapshotLabel}，点击右上角可刷新待上市日历。`,
  },
});

function NewStockDetail() {
  const { sectionKey } = useParams();
  const navigate = useNavigate();
  const [ahSectionState, setAhSectionState] = useState(buildInitialAhSectionState);
  const [cbondState, setCbondState] = useState(buildInitialCbondState);
  const [cbondCalendarState, setCbondCalendarState] = useState(buildInitialCbondCalendarState);

  const cbondStats = useMemo(
    () => (sectionKey === 'cbond' ? buildCbondFirstDayStats(cbondState.rows) : null),
    [sectionKey, cbondState.rows]
  );

  const section = newStockSections.find((s) => s.key === sectionKey);
  const activeAhSection = AH_SECTION_CONFIGS[sectionKey];
  const activeAhState = activeAhSection ? ahSectionState[sectionKey] : null;

  const loadAhSectionData = useCallback(async (targetSectionKey) => {
    const config = AH_SECTION_CONFIGS[targetSectionKey];
    if (!config) {
      return;
    }

    if (config.pairs.length === 0) {
      setAhSectionState((prevState) => ({
        ...prevState,
        [targetSectionKey]: {
          rows: [],
          loading: false,
          meta: {
            mode: 'fallback',
            fetchedAt: config.fallbackMeta.snapshotTime,
            fxRate: config.fallbackMeta.fxRate,
            livePairCount: 0,
            totalPairs: 0,
            usedFallbackRate: true,
            message: config.emptyText,
          },
        },
      }));
      return;
    }

    setAhSectionState((prevState) => ({
      ...prevState,
      [targetSectionKey]: {
        ...prevState[targetSectionKey],
        loading: true,
      },
    }));

    try {
      const [quoteResponse, fxResponse] = await Promise.all([
        fetch(`${TENCENT_QUOTE_ENDPOINT}${buildTencentSymbols(config.pairs, config.aQuotePrefix).join(',')}`),
        fetch(FX_ENDPOINT),
      ]);

      if (!quoteResponse.ok) {
        throw new Error(`quote ${quoteResponse.status}`);
      }

      const quoteText = await quoteResponse.text();
      const quoteMap = parseTencentQuoteText(quoteText);
      const fxPayload = fxResponse.ok ? await fxResponse.json() : null;
      const liveFxRate = Number(fxPayload?.rates?.CNY);
      const fxRate = Number.isFinite(liveFxRate)
        ? liveFxRate
        : config.fallbackMeta.fxRate;
      const { rows, livePairCount } = buildAhRows({
        pairs: config.pairs,
        fallbackRowsByACode: AH_FALLBACK_ROWS_BY_A_CODE[targetSectionKey],
        quoteMap,
        fxRate,
        displayLimit: config.displayLimit,
        aQuotePrefix: config.aQuotePrefix,
      });
      const usedFallbackRate = !Number.isFinite(liveFxRate);
      const liveCoverageMessage =
        livePairCount === config.pairs.length
          ? '已刷新到最新网络行情。'
          : `已刷新 ${livePairCount}/${config.pairs.length} 只实时行情，其余回退到快照。`;

      setAhSectionState((prevState) => ({
        ...prevState,
        [targetSectionKey]: {
          rows,
          loading: false,
          meta: {
            mode: 'live',
            fetchedAt: formatShanghaiTimestamp(),
            fxRate,
            livePairCount,
            totalPairs: config.pairs.length,
            usedFallbackRate,
            message: usedFallbackRate
              ? `${liveCoverageMessage} 汇率接口异常，暂用快照汇率。`
              : liveCoverageMessage,
          },
        },
      }));
    } catch (error) {
      console.error(`加载 ${targetSectionKey} A/H 行情失败:`, error);
      setAhSectionState((prevState) => ({
        ...prevState,
        [targetSectionKey]: {
          rows: config.filteredFallbackRows,
          loading: false,
          meta: {
            mode: 'fallback',
            fetchedAt: config.fallbackMeta.snapshotTime,
            fxRate: config.fallbackMeta.fxRate,
            livePairCount: 0,
            totalPairs: config.pairs.length,
            usedFallbackRate: true,
            message: `实时接口异常，当前展示 ${config.fallbackMeta.snapshotLabel}。`,
          },
        },
      }));
    }
  }, []);

  const loadCbondData = useCallback(async () => {
    let currentRows = cbondFirstDayRows;
    setCbondState((prevState) => {
      currentRows = prevState.rows;
      return {
        ...prevState,
        loading: true,
      };
    });
    setCbondCalendarState((prevState) => ({
      ...prevState,
      loading: true,
    }));

    try {
      const [firstDayResult, calendarResult] = await Promise.all([
        fetchCbondFirstDayUpdates(currentRows),
        fetchCbondUpcomingCalendar(),
      ]);

      setCbondState({
        rows: firstDayResult.rows,
        loading: false,
        meta: {
          mode: firstDayResult.updateCount > 0 ? 'live' : 'fallback',
          fetchedAt: firstDayResult.fetchedAt,
          rangeStart: firstDayResult.rangeStart,
          rangeEnd: firstDayResult.rangeEnd,
          source: firstDayResult.source,
          message: firstDayResult.message,
          liveRowCount: firstDayResult.updateCount,
          totalListed: firstDayResult.rows.length,
        },
      });
      setCbondCalendarState({
        rows: calendarResult.rows,
        loading: false,
        meta: {
          mode: 'live',
          fetchedAt: calendarResult.fetchedAt,
          source: calendarResult.source,
          message: calendarResult.message,
        },
      });
    } catch (error) {
      console.error('加载可转债数据失败:', error);
      setCbondState((prevState) => ({
        ...prevState,
        loading: false,
        meta: {
          ...prevState.meta,
          mode: 'fallback',
          message: `实时接口异常，当前展示 ${cbondFirstDayMeta.snapshotLabel}。`,
        },
      }));
      setCbondCalendarState((prevState) => ({
        ...prevState,
        loading: false,
        meta: {
          ...prevState.meta,
          mode: 'fallback',
          message: `实时接口异常，当前展示 ${cbondUpcomingMeta.snapshotLabel}。`,
        },
      }));
    }
  }, []);

  useEffect(() => {
    if (activeAhSection) {
      loadAhSectionData(sectionKey);
    }
  }, [activeAhSection, loadAhSectionData, sectionKey]);

  useEffect(() => {
    if (sectionKey === 'cbond') {
      loadCbondData();
    }
  }, [sectionKey, loadCbondData]);

  const activeAhMetaLines = useMemo(() => {
    if (!activeAhSection || !activeAhState) {
      return [];
    }

    return [
      `状态：${activeAhState.meta.message}`,
      `更新时间：${activeAhState.meta.fetchedAt}（北京时间）`,
      `筛选范围：${activeAhSection.scopeText}；按 (H-A)/A 从大到小取前 ${activeAhSection.displayLimit}`,
      `数据源：腾讯财经公开行情；汇率源：${activeAhSection.fallbackMeta.fxSource}；港元兑人民币：${activeAhState.meta.fxRate.toFixed(6)}`,
      '口径：(H 股港元价格 × 港元兑人民币 - A 股人民币价格) / A 股人民币价格',
    ];
  }, [activeAhSection, activeAhState]);

  if (sectionKey === 'web3') {
    return <Navigate to="/new-stock/cbond" replace />;
  }

  if (!section) {
    return <Navigate to="/new-stock" replace />;
  }

  return (
    <div className="equation-tab-page" style={{ background: '#fff' }}>
      <div
        style={{
          position: 'sticky',
          top: 0,
          zIndex: 10,
          background: '#fff',
          padding: '12px 16px',
          borderBottom: '1px solid #E5E5EA',
          display: 'flex',
          alignItems: 'center',
          gap: '12px',
        }}
      >
        <Button
          type="text"
          icon={<ArrowLeftOutlined />}
          onClick={() => navigate(-1)}
          style={{
            padding: '4px 8px',
            display: 'flex',
            alignItems: 'center',
            gap: '4px',
            color: 'rgba(0, 0, 0, 0.88)',
          }}
        >
          返回
        </Button>
      </div>

      <div style={{ padding: '16px' }}>
        <Card
          title={section.title}
          extra={
            activeAhSection || sectionKey === 'cbond' ? (
              <Button
                size="small"
                icon={<ReloadOutlined />}
                loading={
                  activeAhSection
                    ? activeAhState?.loading
                    : cbondState.loading || cbondCalendarState.loading
                }
                onClick={() =>
                  sectionKey === 'cbond' ? loadCbondData() : loadAhSectionData(sectionKey)
                }
              >
                刷新新债
              </Button>
            ) : null
          }
          style={{
            borderRadius: '8px',
            overflow: 'hidden',
          }}
          styles={{
            title: {
              fontSize: 18,
              fontWeight: 600,
            },
          }}
          bodyStyle={{ padding: '16px' }}
        >
          {activeAhSection && (
            <p
              style={{
                margin: '0 0 14px 0',
                color: 'rgba(0, 0, 0, 0.85)',
                fontSize: 16,
                fontWeight: 600,
                lineHeight: 1.75,
              }}
            >
              {activeAhSection.intro}
            </p>
          )}
          <div
            style={{
              color: 'rgba(0, 0, 0, 0.85)',
              fontSize: 16,
              fontWeight: 600,
              lineHeight: 1.75,
            }}
          >
            {section.content.map((para, i) => (
              <p key={i} style={{ margin: 0, marginBottom: i < section.content.length - 1 ? 14 : 0 }}>
                {para}
              </p>
            ))}
          </div>
          {sectionKey === 'cbond' && (
            <div style={{ marginTop: 24, width: '100%' }}>
              <h3 style={{ margin: '0 0 10px 0', fontSize: 17, fontWeight: 700 }}>可转债待上市日历</h3>
              <div
                style={{
                  marginBottom: 12,
                  padding: '12px 14px',
                  borderRadius: 8,
                  background: '#fafafa',
                  border: '1px solid #E5E5EA',
                }}
              >
                {[
                  `状态：${cbondCalendarState.meta.message}`,
                  `更新时间：${cbondCalendarState.meta.fetchedAt}${cbondCalendarState.meta.mode === 'live' ? '（北京时间）' : ''}`,
                  `说明：展示尚未上市的可转债，按预计上市日由近到远排列（越靠近今天越靠上）。数据源：${cbondCalendarState.meta.source}。`,
                ].map((line) => (
                  <p
                    key={line}
                    style={{
                      margin: 0,
                      marginBottom: line.startsWith('说明') ? 0 : 6,
                      color: 'rgba(0, 0, 0, 0.65)',
                      fontSize: 13,
                      lineHeight: 1.6,
                    }}
                  >
                    {line}
                  </p>
                ))}
              </div>
              <Table
                size="small"
                rowKey="code"
                pagination={false}
                columns={cbondUpcomingColumns}
                dataSource={cbondCalendarState.rows}
                loading={cbondCalendarState.loading}
                locale={{ emptyText: '近期暂无待上市可转债' }}
                scroll={{ x: 'max-content' }}
                style={{ width: '100%' }}
              />
            </div>
          )}
          {cbondStats && (
            <div style={{ marginTop: 24, width: '100%' }}>
              <h3 style={{ margin: '0 0 10px 0', fontSize: 17, fontWeight: 700 }}>
                三、近一年新债上市首日最大涨幅统计（重点与 50% 对比）
              </h3>
              <div
                style={{
                  marginBottom: 12,
                  padding: '12px 14px',
                  borderRadius: 8,
                  background: '#fafafa',
                  border: '1px solid #E5E5EA',
                }}
              >
                {[
                  `状态：${cbondState.meta.message}`,
                  `更新时间：${cbondState.meta.fetchedAt}${cbondState.meta.mode === 'live' ? '（北京时间）' : ''}`,
                  `样本：${cbondState.meta.rangeStart} ~ ${cbondState.meta.rangeEnd} 在沪深北市场新上市的可转债共 ${cbondStats.total} 只。`,
                  `口径：涨幅以发行面值 100 元为基准，首日最大涨幅 =（首日最高价 - 100）/ 100。数据源：${cbondState.meta.source}。`,
                  `首日最大涨幅：均值 ${cbondStats.maxAvg}%，中位数 ${cbondStats.maxMedian}%，最低 ${cbondStats.maxMin}%，最高 ${cbondStats.maxMax}%（25 分位 ${cbondStats.maxP25}%）。`,
                  `与 50% 对比：${cbondStats.maxGeBenchmark}/${cbondStats.total} 只（${cbondStats.maxGeBenchmarkPct}%）盘中最高涨幅达到或超过 50%；仅 ${cbondStats.total - cbondStats.maxGeBenchmark} 只未达 50%。`,
                  `若不做日内高抛、持有到收盘：${cbondStats.closeGeBenchmark}/${cbondStats.total} 只（${cbondStats.closeGeBenchmarkPct}%）收盘涨幅仍 ≥ 50%，收盘涨幅均值 ${cbondStats.closeAvg}%、中位数 ${cbondStats.closeMedian}%、最低 ${cbondStats.closeMin}%。`,
                  `触及熔断上限：${cbondStats.ceilingHits}/${cbondStats.total} 只（${cbondStats.ceilingHitsPct}%）首日打到 ${cbondStats.ceiling}% 的涨幅天花板（157.3 元二次熔断价），说明 ${cbondStats.maxMedian}% 的中位数其实是被规则封顶的结果，而非市场自然定价。`,
                  `破发情况：样本期内首日收盘破发（低于 100 元）${cbondStats.breakIssuePrice} 只。`,
                  '结论：过去一年新债首日几乎稳定跑赢 50% 这条线，中签一签（1,000 元面值）首日盘中理论收益中位数约 573 元；风险主要不在“会不会涨”，而在“能否在冲高时卖出”——未达 50% 的个例多为大盘、高评级、正股弹性弱的品种。',
                ].map((line, index, list) => (
                  <p
                    key={line}
                    style={{
                      margin: 0,
                      marginBottom: index < list.length - 1 ? 6 : 0,
                      color: 'rgba(0, 0, 0, 0.65)',
                      fontSize: 13,
                      lineHeight: 1.6,
                    }}
                  >
                    {line}
                  </p>
                ))}
              </div>
              {cbondStats.belowBenchmark.length > 0 && (
                <p style={{ margin: '0 0 12px 0', fontSize: 13, color: '#8c8c8c', lineHeight: 1.6 }}>
                  {`未达 50% 的 ${cbondStats.belowBenchmark.length} 只：`}
                  {cbondStats.belowBenchmark
                    .map((row) => `${row.name}(${row.listDate} ${row.maxPct.toFixed(2)}%)`)
                    .join('、')}
                </p>
              )}
              <Table
                size="small"
                rowKey="code"
                pagination={{ pageSize: 20, showSizeChanger: false }}
                columns={cbondFirstDayColumns}
                dataSource={cbondState.rows}
                loading={cbondState.loading}
                scroll={{ x: 'max-content' }}
                style={{ width: '100%' }}
              />
            </div>
          )}
          {activeAhSection && activeAhState && (
            <div style={{ marginTop: 20, width: '100%' }}>
              <div
                style={{
                  marginBottom: 12,
                  padding: '12px 14px',
                  borderRadius: 8,
                  background: '#fafafa',
                  border: '1px solid #E5E5EA',
                }}
              >
                {activeAhMetaLines.map((line) => (
                  <p
                    key={line}
                    style={{
                      margin: 0,
                      marginBottom: line === activeAhMetaLines[activeAhMetaLines.length - 1] ? 0 : 6,
                      color: 'rgba(0, 0, 0, 0.65)',
                      fontSize: 13,
                      lineHeight: 1.6,
                    }}
                  >
                    {line}
                  </p>
                ))}
              </div>
              <Table
                size="small"
                pagination={false}
                columns={szChinextAhArbitrageColumns}
                dataSource={activeAhState.rows}
                loading={activeAhState.loading}
                locale={{
                  emptyText: activeAhSection.emptyText,
                }}
                scroll={{ x: 'max-content' }}
                tableLayout="fixed"
                style={{ width: '100%' }}
              />
            </div>
          )}
        </Card>
      </div>
    </div>
  );
}

export default NewStockDetail;
