// 与 MathProofDetail 等页面共用的 Markdown 渲染

function processInlineFormatting(text) {
  // 先处理代码（避免被其他格式影响）
  text = text.replace(/`([^`\n]+)`/g, '<code style="background: #f5f5f5; padding: 2px 6px; border-radius: 4px; font-family: monospace; font-size: 14px;">$1</code>');
  // 处理粗体
  text = text.replace(/\*\*(.+?)\*\*/g, '<strong style="font-weight: bold; color: #000;">$1</strong>');
  // 处理斜体
  text = text.replace(/\*(.+?)\*/g, '<em style="font-style: italic;">$1</em>');
  // 图片须在链接之前，否则 ![alt](url) 会被当成链接
  text = text.replace(
    /!\[([^\]]*)\]\(([^)]+)\)/g,
    '<img src="$2" alt="$1" style="max-width: 100%; height: auto; display: block; margin: 16px auto;" />'
  );
  // 处理链接
  text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer" style="color: #000; text-decoration: underline;">$1</a>');
  return text;
}


export function markdownToHtml(markdown) {
  // 按行处理，保持原始结构
  const lines = markdown.split('\n');
  const result = [];
  let currentParagraph = [];
  let currentListItems = [];
  let currentNestedListItems = [];
  
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();
    
    // 空行处理
    if (!trimmed) {
      // 结束当前段落
      if (currentParagraph.length > 0) {
        result.push('<p style="margin-bottom: 16px; line-height: 1.8;">' + currentParagraph.join(' ') + '</p>');
        currentParagraph = [];
      }
      // 结束当前列表
      if (currentListItems.length > 0 || currentNestedListItems.length > 0) {
        if (currentNestedListItems.length > 0) {
          // 先处理嵌套列表
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc; margin-left: 20px;">');
          result.push(...currentNestedListItems);
          result.push('</ul>');
          currentNestedListItems = [];
        }
        if (currentListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc;">');
          result.push(...currentListItems);
          result.push('</ul>');
          currentListItems = [];
        }
      }
      continue;
    }
    
    // 代码块（三个反引号）
    if (trimmed.startsWith('```')) {
      // 结束当前段落和列表
      if (currentParagraph.length > 0) {
        result.push('<p style="margin-bottom: 16px; line-height: 1.8;">' + currentParagraph.join(' ') + '</p>');
        currentParagraph = [];
      }
      if (currentListItems.length > 0 || currentNestedListItems.length > 0) {
        if (currentNestedListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc; margin-left: 20px;">');
          result.push(...currentNestedListItems);
          result.push('</ul>');
          currentNestedListItems = [];
        }
        if (currentListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc;">');
          result.push(...currentListItems);
          result.push('</ul>');
          currentListItems = [];
        }
      }
      
      // 收集代码块内容
      let codeContent = [];
      i++;
      while (i < lines.length && !lines[i].trim().startsWith('```')) {
        codeContent.push(lines[i]);
        i++;
      }
      result.push(`<pre style="background: #f5f5f5; padding: 16px; border-radius: 4px; overflow-x: auto; margin: 16px 0;"><code>${codeContent.join('\n').trim()}</code></pre>`);
      continue;
    }
    
    // 标题
    if (trimmed.startsWith('#### ')) {
      if (currentParagraph.length > 0) {
        result.push('<p style="margin-bottom: 16px; line-height: 1.8;">' + currentParagraph.join(' ') + '</p>');
        currentParagraph = [];
      }
      if (currentListItems.length > 0 || currentNestedListItems.length > 0) {
        if (currentNestedListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc; margin-left: 20px;">');
          result.push(...currentNestedListItems);
          result.push('</ul>');
          currentNestedListItems = [];
        }
        if (currentListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc;">');
          result.push(...currentListItems);
          result.push('</ul>');
          currentListItems = [];
        }
      }
      let content = trimmed.substring(5);
      result.push(`<h4 style="font-size: 18px; margin-top: 24px; margin-bottom: 12px; font-weight: bold; color: #000;">${content}</h4>`);
      continue;
    }
    if (trimmed.startsWith('### ')) {
      if (currentParagraph.length > 0) {
        result.push('<p style="margin-bottom: 16px; line-height: 1.8;">' + currentParagraph.join(' ') + '</p>');
        currentParagraph = [];
      }
      if (currentListItems.length > 0 || currentNestedListItems.length > 0) {
        if (currentNestedListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc; margin-left: 20px;">');
          result.push(...currentNestedListItems);
          result.push('</ul>');
          currentNestedListItems = [];
        }
        if (currentListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc;">');
          result.push(...currentListItems);
          result.push('</ul>');
          currentListItems = [];
        }
      }
      let content = trimmed.substring(4);
      result.push(`<h3 style="font-size: 20px; margin-top: 28px; margin-bottom: 14px; font-weight: bold; color: #000;">${content}</h3>`);
      continue;
    }
    if (trimmed.startsWith('## ')) {
      if (currentParagraph.length > 0) {
        result.push('<p style="margin-bottom: 16px; line-height: 1.8;">' + currentParagraph.join(' ') + '</p>');
        currentParagraph = [];
      }
      if (currentListItems.length > 0 || currentNestedListItems.length > 0) {
        if (currentNestedListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc; margin-left: 20px;">');
          result.push(...currentNestedListItems);
          result.push('</ul>');
          currentNestedListItems = [];
        }
        if (currentListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc;">');
          result.push(...currentListItems);
          result.push('</ul>');
          currentListItems = [];
        }
      }
      let content = trimmed.substring(3);
      result.push(`<h2 style="font-size: 24px; margin-top: 32px; margin-bottom: 16px; font-weight: bold; color: #000; border-bottom: 1px solid #e8e8e8; padding-bottom: 8px;">${content}</h2>`);
      continue;
    }
    if (trimmed.startsWith('# ')) {
      if (currentParagraph.length > 0) {
        result.push('<p style="margin-bottom: 16px; line-height: 1.8;">' + currentParagraph.join(' ') + '</p>');
        currentParagraph = [];
      }
      if (currentListItems.length > 0 || currentNestedListItems.length > 0) {
        if (currentNestedListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc; margin-left: 20px;">');
          result.push(...currentNestedListItems);
          result.push('</ul>');
          currentNestedListItems = [];
        }
        if (currentListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc;">');
          result.push(...currentListItems);
          result.push('</ul>');
          currentListItems = [];
        }
      }
      let content = trimmed.substring(2);
      result.push(`<h1 style="font-size: 28px; margin-top: 32px; margin-bottom: 16px; font-weight: bold; color: #000; border-bottom: 1px solid #e8e8e8; padding-bottom: 8px;">${content}</h1>`);
      continue;
    }
    
    // 分隔线
    if (trimmed === '---') {
      if (currentParagraph.length > 0) {
        result.push('<p style="margin-bottom: 16px; line-height: 1.8;">' + currentParagraph.join(' ') + '</p>');
        currentParagraph = [];
      }
      if (currentListItems.length > 0 || currentNestedListItems.length > 0) {
        if (currentNestedListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc; margin-left: 20px;">');
          result.push(...currentNestedListItems);
          result.push('</ul>');
          currentNestedListItems = [];
        }
        if (currentListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc;">');
          result.push(...currentListItems);
          result.push('</ul>');
          currentListItems = [];
        }
      }
      result.push('<hr style="margin: 24px 0; border: none; border-top: 1px solid #e8e8e8;">');
      continue;
    }
    
    // 列表项（嵌套：两个空格 + "-"）
    if (line.match(/^ {2}- /)) {
      // 结束当前段落
      if (currentParagraph.length > 0) {
        result.push('<p style="margin-bottom: 16px; line-height: 1.8;">' + currentParagraph.join(' ') + '</p>');
        currentParagraph = [];
      }
      // 如果之前有普通列表项，先结束它们
      if (currentListItems.length > 0) {
        result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc;">');
        result.push(...currentListItems);
        result.push('</ul>');
        currentListItems = [];
      }
      let content = trimmed.substring(3); // 去掉 "  - "
      // 处理内联格式
      content = processInlineFormatting(content);
      currentNestedListItems.push(`<li style="margin-bottom: 8px; margin-left: 20px;">${content}</li>`);
      continue;
    }
    
    // 列表项（普通："-" 开头）
    if (trimmed.startsWith('- ')) {
      // 结束当前段落
      if (currentParagraph.length > 0) {
        result.push('<p style="margin-bottom: 16px; line-height: 1.8;">' + currentParagraph.join(' ') + '</p>');
        currentParagraph = [];
      }
      // 如果之前有嵌套列表项，先结束它们
      if (currentNestedListItems.length > 0) {
        result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc; margin-left: 20px;">');
        result.push(...currentNestedListItems);
        result.push('</ul>');
        currentNestedListItems = [];
      }
      let content = trimmed.substring(2); // 去掉 "- "
      // 处理内联格式
      content = processInlineFormatting(content);
      currentListItems.push(`<li style="margin-bottom: 8px;">${content}</li>`);
      continue;
    }
    
    // 有序列表项
    const orderedListMatch = trimmed.match(/^(\d+)\. (.+)$/);
    if (orderedListMatch) {
      if (currentParagraph.length > 0) {
        result.push('<p style="margin-bottom: 16px; line-height: 1.8;">' + currentParagraph.join(' ') + '</p>');
        currentParagraph = [];
      }
      if (currentListItems.length > 0 || currentNestedListItems.length > 0) {
        if (currentNestedListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc; margin-left: 20px;">');
          result.push(...currentNestedListItems);
          result.push('</ul>');
          currentNestedListItems = [];
        }
        if (currentListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc;">');
          result.push(...currentListItems);
          result.push('</ul>');
          currentListItems = [];
        }
      }
      let content = orderedListMatch[2];
      content = processInlineFormatting(content);
      result.push(`<ol style="margin-bottom: 16px; padding-left: 24px;"><li style="margin-bottom: 8px;">${content}</li></ol>`);
      continue;
    }
    
    // 表格处理（以|开头的行）
    if (trimmed.startsWith('|') && trimmed.endsWith('|')) {
      // 检查是否是分隔符行（|---|---|），分隔符行的特征是每个单元格都只包含-、:或空白字符
      // 使用更严格的匹配：整行只包含|、-、:和空白字符，且至少包含一个-
      const isSeparator = trimmed.match(/^\|([\s\-:]+\|)+$/) && trimmed.includes('-');
      if (isSeparator) {
        continue;
      }
      
      // 结束当前段落和列表
      if (currentParagraph.length > 0) {
        result.push('<p style="margin-bottom: 16px; line-height: 1.8;">' + currentParagraph.join(' ') + '</p>');
        currentParagraph = [];
      }
      if (currentListItems.length > 0 || currentNestedListItems.length > 0) {
        if (currentNestedListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc; margin-left: 20px;">');
          result.push(...currentNestedListItems);
          result.push('</ul>');
          currentNestedListItems = [];
        }
        if (currentListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc;">');
          result.push(...currentListItems);
          result.push('</ul>');
          currentListItems = [];
        }
      }
      
      // 收集连续的表格行（跳过分隔符行）
      let tableRows = [];
      let j = i;
      let hasSeparator = false;
      
      while (j < lines.length) {
        const tableLine = lines[j].trim();
        if (tableLine.startsWith('|') && tableLine.endsWith('|')) {
          // 检查是否是分隔符行，分隔符行的特征是每个单元格都只包含-、:或空白字符
          const isSeparator = tableLine.match(/^\|([\s\-:]+\|)+$/) && tableLine.includes('-');
          if (isSeparator) {
            hasSeparator = true;
            j++; // 跳过分隔符行，不加入tableRows
            continue;
          }
          // 普通表格行，加入数组
          tableRows.push(tableLine);
          j++;
        } else {
          break;
        }
      }
      
      // 处理表格
      if (tableRows.length > 0) {
        let tableHtml = '<table style="border-collapse: collapse; width: 100%; margin: 16px 0; border: 1px solid #e8e8e8;">';
        
        if (hasSeparator && tableRows.length > 0) {
          // 有分隔符，第一行是表头
          const headerRow = tableRows[0];
          const headerCells = headerRow.split('|').slice(1, -1).map(c => c.trim());
          tableHtml += '<thead><tr>';
          for (const cell of headerCells) {
            const cellContent = processInlineFormatting(cell);
            tableHtml += `<th style="border: 1px solid #e8e8e8; padding: 8px; text-align: left; font-weight: bold; background-color: #f5f5f5;">${cellContent}</th>`;
          }
          tableHtml += '</tr></thead><tbody>';
          
          // 处理数据行（从第二行开始）
          for (let rowIdx = 1; rowIdx < tableRows.length; rowIdx++) {
            const row = tableRows[rowIdx];
            const cells = row.split('|').slice(1, -1).map(c => c.trim());
            tableHtml += '<tr>';
            for (const cell of cells) {
              const cellContent = processInlineFormatting(cell);
              tableHtml += `<td style="border: 1px solid #e8e8e8; padding: 8px;">${cellContent}</td>`;
            }
            tableHtml += '</tr>';
          }
        } else {
          // 没有分隔符，所有行都是数据行
          tableHtml += '<tbody>';
          for (let rowIdx = 0; rowIdx < tableRows.length; rowIdx++) {
            const row = tableRows[rowIdx];
            const cells = row.split('|').slice(1, -1).map(c => c.trim());
            tableHtml += '<tr>';
            for (const cell of cells) {
              const cellContent = processInlineFormatting(cell);
              tableHtml += `<td style="border: 1px solid #e8e8e8; padding: 8px;">${cellContent}</td>`;
            }
            tableHtml += '</tr>';
          }
        }
        
        tableHtml += '</tbody></table>';
        result.push(tableHtml);
        
        // 跳过已处理的表格行（包括分隔符）
        i = j - 1;
        continue;
      }
    }

    // 引用块（> 开头）
    if (trimmed.startsWith('>')) {
      if (currentParagraph.length > 0) {
        result.push('<p style="margin-bottom: 16px; line-height: 1.8;">' + currentParagraph.join(' ') + '</p>');
        currentParagraph = [];
      }
      if (currentListItems.length > 0 || currentNestedListItems.length > 0) {
        if (currentNestedListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc; margin-left: 20px;">');
          result.push(...currentNestedListItems);
          result.push('</ul>');
          currentNestedListItems = [];
        }
        if (currentListItems.length > 0) {
          result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc;">');
          result.push(...currentListItems);
          result.push('</ul>');
          currentListItems = [];
        }
      }
      const inner = trimmed.replace(/^>\s?/, '').trim();
      result.push(
        '<blockquote style="border-left: 4px solid #d9d9d9; padding: 8px 0 8px 16px; margin: 16px 0; color: #595959;">' +
          processInlineFormatting(inner) +
          '</blockquote>'
      );
      continue;
    }

    // 普通文本行
    currentParagraph.push(trimmed);
  }
  
  // 处理剩余的段落和列表
  if (currentParagraph.length > 0) {
    result.push('<p style="margin-bottom: 16px; line-height: 1.8;">' + currentParagraph.join(' ') + '</p>');
  }
  if (currentNestedListItems.length > 0) {
    result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc; margin-left: 20px;">');
    result.push(...currentNestedListItems);
    result.push('</ul>');
  }
  if (currentListItems.length > 0) {
    result.push('<ul style="margin-bottom: 16px; padding-left: 24px; list-style-type: disc;">');
    result.push(...currentListItems);
    result.push('</ul>');
  }
  
  // 处理内联格式和链接
  let finalHtml = result.join('\n');
  
  // 处理内联格式（粗体、斜体、行内代码、图片、链接）
  finalHtml = finalHtml.replace(/\*\*(.+?)\*\*/g, '<strong style="font-weight: bold; color: #000;">$1</strong>');
  finalHtml = finalHtml.replace(/\*(.+?)\*/g, '<em style="font-style: italic;">$1</em>');
  finalHtml = finalHtml.replace(/`([^`\n]+)`/g, '<code style="background: #f5f5f5; padding: 2px 6px; border-radius: 4px; font-family: monospace; font-size: 14px;">$1</code>');
  finalHtml = finalHtml.replace(
    /!\[([^\]]*)\]\(([^)]+)\)/g,
    '<img src="$2" alt="$1" style="max-width: 100%; height: auto; display: block; margin: 16px auto;" />'
  );
  finalHtml = finalHtml.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer" style="color: #000; text-decoration: underline;">$1</a>');
  return finalHtml;
}

export function applyMathProofHeadingLinkCleanup(finalHtml) {
  const targetTexts = ['策略概述', '情景一：指数ETF期权备兑策略', '情景二：多只个股期权备兑策略', '结论'];
  let html = finalHtml;
  targetTexts.forEach((targetText) => {
    const regex = new RegExp(`(<h[1-4][^>]*>)([^<]*${targetText.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}[^<]*)(</h[1-4]>)`, 'g');
    html = html.replace(regex, (match, openTag, content, closeTag) => {
      content = content.replace(/<a([^>]*)style="([^"]*)"([^>]*)>/g, (linkMatch, before, style, after) => {
        const newStyle = style.replace(/text-decoration:\s*underline[^;]*;?/g, '').trim();
        return `<a${before}style="${newStyle}; text-decoration: none;"${after}>`;
      });
      content = content.replace(/<a([^>]*)>/g, (linkMatch, attrs) => {
        if (!attrs.includes('style=')) {
          return `<a${attrs} style="text-decoration: none;">`;
        }
        return linkMatch;
      });
      return openTag + content + closeTag;
    });
  });
  return html;
}
