const percentile = (sortedValues, p) => {
  if (sortedValues.length === 0) return 0;
  const idx = (sortedValues.length - 1) * p;
  const lower = Math.floor(idx);
  const upper = Math.ceil(idx);
  if (lower === upper) return sortedValues[lower];
  return sortedValues[lower] + (sortedValues[upper] - sortedValues[lower]) * (idx - lower);
};

const round2 = (value) => Number(value.toFixed(2));

/** 基于快照现算统计口径，避免手写数字与明细不一致 */
export const buildCbondFirstDayStats = (rows = cbondFirstDayRows, benchmark = cbondFirstDayMeta.benchmark) => {
  const total = rows.length;
  const maxList = rows.map((row) => row.maxPct).sort((a, b) => a - b);
  const closeList = rows.map((row) => row.closePct).sort((a, b) => a - b);
  const sum = (list) => list.reduce((acc, value) => acc + value, 0);
  const countGe = (list, threshold) => list.filter((value) => value >= threshold).length;
  const ceilingHits = rows.filter((row) => row.maxPct >= cbondFirstDayMeta.ceiling - 0.01).length;
  const belowBenchmark = rows
    .filter((row) => row.maxPct < benchmark)
    .sort((a, b) => a.maxPct - b.maxPct);

  return {
    total,
    benchmark,
    ceiling: cbondFirstDayMeta.ceiling,
    maxAvg: round2(sum(maxList) / total),
    maxMedian: round2(percentile(maxList, 0.5)),
    maxMin: round2(maxList[0]),
    maxMax: round2(maxList[maxList.length - 1]),
    maxP25: round2(percentile(maxList, 0.25)),
    closeAvg: round2(sum(closeList) / total),
    closeMedian: round2(percentile(closeList, 0.5)),
    closeMin: round2(closeList[0]),
    maxGeBenchmark: countGe(maxList, benchmark),
    closeGeBenchmark: countGe(closeList, benchmark),
    maxGeBenchmarkPct: round2((countGe(maxList, benchmark) / total) * 100),
    closeGeBenchmarkPct: round2((countGe(closeList, benchmark) / total) * 100),
    ceilingHits,
    ceilingHitsPct: round2((ceilingHits / total) * 100),
    breakIssuePrice: closeList.filter((value) => value < 0).length,
    belowBenchmark,
  };
};

