import React, { useEffect, useState } from 'react';
import { Button, Card, Table, Tag, message } from 'antd';
import { ArrowLeftOutlined, ReloadOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import request from '../utils/request';

const SOURCE_LABELS = {
  price_alert: '价格告警',
  liquidation_arb: '清算套利',
  auto_sell: '自动卖出',
  crypto_option_delivery: '期权交割',
  new_stock_bark_forward: '新股转发',
  pry_board: '撬板扫描',
};

const ACTION_LABELS = {
  buy: '买入',
  sell: '卖出',
  drop: '跌破',
  rise: '涨过',
  option_sell: '卖出期权',
  option_buy_hint: '买入期权',
  alert: '提醒',
};

function formatTime(value) {
  if (!value) return '-';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return value;
  return d.toLocaleString('zh-CN', { hour12: false });
}

function PushSignalHistory() {
  const navigate = useNavigate();
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);

  const fetchHistory = async () => {
    setLoading(true);
    try {
      const res = await request('/api/subscribe/push-signal-history?limit=100', { method: 'GET' });
      const rows = res?.data?.items;
      setItems(Array.isArray(rows) ? rows : []);
    } catch (e) {
      message.error(e?.message || '加载推送历史失败');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchHistory();
  }, []);

  const columns = [
    {
      title: '时间',
      dataIndex: 'created_at',
      key: 'created_at',
      width: 170,
      render: formatTime,
    },
    {
      title: '来源',
      dataIndex: 'source',
      key: 'source',
      width: 110,
      render: (source) => SOURCE_LABELS[source] || source || '-',
    },
    {
      title: '动作',
      dataIndex: 'action',
      key: 'action',
      width: 90,
      render: (action) => ACTION_LABELS[action] || action || '-',
    },
    {
      title: '标的',
      key: 'symbol',
      width: 100,
      render: (_, row) => row.symbol || row.market || '-',
    },
    {
      title: '标题',
      dataIndex: 'title',
      key: 'title',
      ellipsis: true,
    },
    {
      title: '正文',
      dataIndex: 'content',
      key: 'content',
      ellipsis: true,
    },
    {
      title: '渠道',
      dataIndex: 'channel',
      key: 'channel',
      width: 90,
      render: (channel) => channel || '-',
    },
    {
      title: '状态',
      dataIndex: 'send_ok',
      key: 'send_ok',
      width: 90,
      render: (ok, row) => ok ? <Tag color="success">成功</Tag> : <Tag color="error" title={row.send_error || ''}>失败</Tag>,
    },
  ];

  return (
    <div className="equation-tab-page">
      <div style={{
        position: 'sticky',
        top: 0,
        zIndex: 1000,
        background: '#fff',
        padding: '16px',
        borderBottom: '1px solid #E5E5EA',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}>
        <Button type="text" icon={<ArrowLeftOutlined />} onClick={() => navigate('/subscribe-stock')}>
          返回
        </Button>
        <Button type="text" icon={<ReloadOutlined />} onClick={fetchHistory} loading={loading}>
          刷新
        </Button>
      </div>

      <Card
        title="推送历史"
        style={{ margin: '16px', marginTop: 24, borderRadius: 8 }}
        bodyStyle={{ padding: 12, overflowX: 'auto' }}
      >
        <Table
          columns={columns}
          dataSource={items}
          rowKey="id"
          loading={loading}
          size="small"
          scroll={{ x: 'max-content' }}
          pagination={{
            pageSize: 20,
            showSizeChanger: true,
            showTotal: (total) => `共 ${total} 条`,
          }}
        />
      </Card>
    </div>
  );
}

export default PushSignalHistory;
