import React, { useEffect, useState } from 'react';
import { Card, Row, Col, Switch, message } from 'antd';
import { RightOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import { newStockSections } from '../data/newStockSections';
import request from '../utils/request';

const ROOT_USER_ID = 100002001;

const OUTER_CARD_STYLE = {
  margin: '16px',
  marginBottom: 24,
  borderRadius: '14px',
  boxShadow: '0 2px 8px rgba(0,0,0,0.06)',
  overflow: 'hidden',
};

const INNER_CARD_STYLE = {
  borderRadius: '12px',
  transition: 'all 0.2s ease',
  cursor: 'pointer',
};

function NewStockIssuance() {
  const navigate = useNavigate();
  const [notifyEnabled, setNotifyEnabled] = useState(true);
  const [notifyLoading, setNotifyLoading] = useState(false);
  const [isRootUser, setIsRootUser] = useState(false);

  useEffect(() => {
    const loadNotifyState = async () => {
      try {
        const response = await request('/api/subscribe/new-stock-notify', {
          method: 'GET',
        });
        if (response?.code === 200 && response.data) {
          setNotifyEnabled(!!response.data.enabled);
        }
      } catch (error) {
        console.error('加载新股推送开关失败:', error);
      }
    };
    loadNotifyState();
  }, []);

  useEffect(() => {
    const fetchMe = async () => {
      try {
        const response = await request('/api/auth/me', { method: 'GET' });
        setIsRootUser(response?.code === 200 && response.data?.user_id === ROOT_USER_ID);
      } catch (_) {}
    };
    fetchMe();
  }, []);

  const handleNotifyChange = async (checked) => {
    setNotifyLoading(true);
    try {
      const response = await request('/api/subscribe/new-stock-notify', {
        method: 'PUT',
        body: JSON.stringify({ enabled: checked }),
      });
      if (response?.code === 200) {
        setNotifyEnabled(checked);
        message.success(checked ? '已开启新股推送提醒' : '已关闭新股推送提醒');
      } else {
        message.error(response?.message || '保存开关失败');
      }
    } catch (error) {
      console.error('保存新股推送开关失败:', error);
      message.error('保存开关失败，请稍后重试');
    } finally {
      setNotifyLoading(false);
    }
  };

  return (
    <div className="equation-tab-page">
      <Card style={OUTER_CARD_STYLE} bodyStyle={{ padding: '12px 16px' }}>
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            gap: '12px',
          }}
        >
          <div>
            <div style={{ fontSize: '15px', fontWeight: 500, color: '#1C1C1E' }}>
              新股推送提醒
            </div>
            <div style={{ fontSize: '12px', color: '#8E8E93', marginTop: '4px' }}>
              开启后将在有新发行信息时推送通知
            </div>
          </div>
          <Switch
            checked={notifyEnabled}
            loading={notifyLoading}
            onChange={handleNotifyChange}
          />
        </div>
      </Card>

      {isRootUser && (
        <Card title="Root 管理" style={OUTER_CARD_STYLE} bodyStyle={{ padding: '12px' }}>
          <Card
            size="small"
            hoverable
            style={INNER_CARD_STYLE}
            bodyStyle={{ padding: '12px' }}
            onClick={() => navigate('/new-stock/support')}
          >
            <div
              style={{
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
              }}
            >
              <span style={{ fontSize: '15px', color: '#1C1C1E' }}>添加支持股票</span>
              <RightOutlined
                style={{
                  fontSize: '16px',
                  color: '#AEAEB2',
                  flexShrink: 0,
                }}
              />
            </div>
          </Card>
        </Card>
      )}

      {newStockSections.map((item) => (
        <Card
          key={item.key}
          title={item.title}
          style={OUTER_CARD_STYLE}
          bodyStyle={{ padding: '12px' }}
        >
          <Row gutter={[12, 12]}>
            <Col span={24}>
              <Card
                size="small"
                hoverable
                style={INNER_CARD_STYLE}
                bodyStyle={{ padding: '12px' }}
                onClick={() => navigate(`/new-stock/${item.key}`)}
              >
                <div
                  style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                  }}
                >
                  <span style={{ fontSize: '15px', color: '#1C1C1E' }}>{item.rowTitle}</span>
                  <RightOutlined
                    style={{
                      fontSize: '16px',
                      color: '#AEAEB2',
                      flexShrink: 0,
                    }}
                  />
                </div>
              </Card>
            </Col>
          </Row>
        </Card>
      ))}
    </div>
  );
}

export default NewStockIssuance;
