import React, { useState, useEffect, useCallback } from 'react';
import { Card, Table, Select, Pagination, message, Popover, Descriptions, AutoComplete } from 'antd';
import { useNavigate } from 'react-router-dom';
import request from '../utils/request';

const { Option } = Select;

function OptionRate() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [stockOptions, setStockOptions] = useState([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [pageSize] = useState(15);
  const [sortBy, setSortBy] = useState('');
  const [sortOrder, setSortOrder] = useState('desc');
  const [windowWidth, setWindowWidth] = useState(window.innerWidth);
  const [searchOptions, setSearchOptions] = useState([]);
  const [searchLoading, setSearchLoading] = useState(false);
  const [searchValue, setSearchValue] = useState('');
  const [selectedStockSymbol, setSelectedStockSymbol] = useState('');

  // 监听窗口大小变化
  useEffect(() => {
    const handleResize = () => {
      setWindowWidth(window.innerWidth);
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // 搜索股票
  const handleSearch = async (value) => {
    if (!value) {
      setSearchOptions([]);
      return;
    }

    try {
      setSearchLoading(true);
      const response = await request('/api/stock/search', {
        method: 'POST',
        body: JSON.stringify({ name: value }),
      });

      if (response.code === 200 && Array.isArray(response.data)) {
        const stockOptions = response.data.map(stock => ({
          value: stock.symbol,
          label: (
            <div>
              <div>{stock.symbol}</div>
              <div style={{ fontSize: '12px', color: '#8E8E93' }}>{stock.chinese_name}</div>
            </div>
          ),
          stock: stock
        }));
        setSearchOptions(stockOptions);
      } else {
        setSearchOptions([]);
      }
    } catch (error) {
      console.error('搜索股票失败:', error);
      setSearchOptions([]);
    } finally {
      setSearchLoading(false);
    }
  };

  const handleSelect = (value) => {
    setSelectedStockSymbol(value);
    setSearchValue('');
    setPage(1); // 重置到第一页
  };

  // 加载股票期权数据
  const loadStockOptions = useCallback(async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams({
        page: page.toString(),
        page_size: pageSize.toString(),
      });
      if (sortBy) {
        params.append('sort_by', sortBy);
        params.append('sort_order', sortOrder);
      }
      if (selectedStockSymbol) {
        params.append('symbol', selectedStockSymbol);
      }

      const response = await request(`/api/option-rate/stocks?${params.toString()}`);
      if (response.code === 200 && response.data) {
        setStockOptions(response.data.list || []);
        setTotal(response.data.total || 0);
      } else {
        message.error(response.message || '获取期权数据失败');
        setStockOptions([]);
        setTotal(0);
      }
    } catch (error) {
      console.error('加载期权数据失败:', error);
      message.error('加载期权数据失败，请稍后重试');
      setStockOptions([]);
      setTotal(0);
    } finally {
      setLoading(false);
    }
  }, [page, pageSize, sortBy, sortOrder, selectedStockSymbol]);

  useEffect(() => {
    loadStockOptions();
  }, [loadStockOptions]);

  const handleSortChange = (value) => {
    if (value === '') {
      setSortBy('');
      setSortOrder('desc');
    } else {
      setSortBy(value);
      setSortOrder('desc'); // 默认降序
    }
    setPage(1); // 重置到第一页
  };

  const handlePageChange = (newPage) => {
    setPage(newPage);
  };

  // 根据屏幕宽度计算是否启用横向滚动
  // 优化后的列宽总和约560px，如果屏幕宽度 >= 800px，则不需要滚动
  const needsScroll = windowWidth < 800;

  // 渲染期权详细信息
  const renderOptionDetails = (option, market) => {
    if (!option) return null;

    const currency = market === 'HK' ? 'HK$' : '$';
    const items = [
      {
        key: 'symbol',
        label: '期权代码',
        children: option.symbol || '-',
      },
      {
        key: 'put_call',
        label: '期权类型',
        children: option.put_call === 'CALL' ? '看涨期权' : '看跌期权',
      },
      {
        key: 'expiry_date',
        label: '到期日',
        children: option.expiry_date || '-',
      },
      {
        key: 'strike_price',
        label: '行权价',
        children: option.strike_price ? `${currency}${option.strike_price.toFixed(2)}` : '-',
      },
      {
        key: 'latest_price',
        label: '最新价',
        children: option.latest_price !== undefined && option.latest_price !== null 
          ? `${currency}${option.latest_price.toFixed(2)}` 
          : '-',
      },
      {
        key: 'bid_price',
        label: '买价',
        children: option.bid_price !== undefined && option.bid_price !== null 
          ? `${currency}${option.bid_price.toFixed(2)}` 
          : '-',
      },
      {
        key: 'ask_price',
        label: '卖价',
        children: option.ask_price !== undefined && option.ask_price !== null 
          ? `${currency}${option.ask_price.toFixed(2)}` 
          : '-',
      },
      {
        key: 'pre_close',
        label: '昨收价',
        children: option.pre_close !== undefined && option.pre_close !== null 
          ? `${currency}${option.pre_close.toFixed(2)}` 
          : '-',
      },
      {
        key: 'volume',
        label: '成交量',
        children: option.volume !== undefined && option.volume !== null 
          ? option.volume.toLocaleString() 
          : '-',
      },
      {
        key: 'open_interest',
        label: '持仓量',
        children: option.open_interest !== undefined && option.open_interest !== null 
          ? option.open_interest.toLocaleString() 
          : '-',
      },
      {
        key: 'multiplier',
        label: '合约乘数',
        children: option.multiplier !== undefined && option.multiplier !== null 
          ? option.multiplier.toLocaleString() 
          : '-',
      },
      {
        key: 'profit_percent',
        label: '年化收益率',
        children: option.profit_percent !== undefined && option.profit_percent !== null 
          ? `${option.profit_percent.toFixed(2)}%` 
          : '-',
      },
    ];

    return (
      <Descriptions
        column={1}
        size="small"
        bordered
        style={{ maxWidth: '400px' }}
        items={items}
      />
    );
  };

  const columns = [
    {
      title: '股票名称',
      dataIndex: 'chinese_name',
      key: 'chinese_name',
      width: needsScroll ? 72 : 80,
      fixed: 'left',
      ellipsis: true,
      render: (text, record) => (
        <a
          href={`#/option-rate/history/${record.symbol}`}
          onClick={(e) => {
            e.preventDefault();
            navigate(`/option-rate/history/${record.symbol}`);
          }}
          style={{ color: '#1677ff', cursor: 'pointer' }}
        >
          {text}
        </a>
      ),
    },
    {
      title: '当前价',
      dataIndex: 'current_price',
      key: 'current_price',
      width: needsScroll ? 100 : 85,
      align: 'right',
      render: (value) => {
        if (value === undefined || value === null || value === 0) {
          return <span style={{ color: '#8E8E93' }}>-</span>;
        }
        return <span style={{ fontWeight: 'bold' }}>${value.toFixed(2)}</span>;
      },
    },
    {
      title: '同比增长',
      dataIndex: 'eps_yoy_change',
      key: 'eps_yoy_change',
      width: needsScroll ? 100 : 90,
      align: 'right',
      sorter: true,
      sortOrder: sortBy === 'eps_yoy_change' ? (sortOrder === 'asc' ? 'ascend' : 'descend') : null,
      render: (value) => {
        if (value === undefined || value === null) {
          return <span style={{ color: '#8E8E93' }}>-</span>;
        }
        const color = value > 0 ? '#cf1322' : value < 0 ? '#389e0d' : '#8E8E93';
        const prefix = value > 0 ? '+' : '';
        return (
          <span style={{ fontWeight: 'bold', color }}>
            {prefix}{value.toFixed(0)}%
          </span>
        );
      },
    },
    {
      title: '扣净市盈率',
      dataIndex: 'deduct_net_asset_pe',
      key: 'deduct_net_asset_pe',
      width: needsScroll ? 110 : 100,
      align: 'right',
      sorter: true,
      sortOrder: sortBy === 'deduct_net_asset_pe' ? (sortOrder === 'asc' ? 'ascend' : 'descend') : null,
      render: (value) => {
        if (value === undefined || value === null || value <= 0) {
          return <span style={{ color: '#8E8E93' }}>-</span>;
        }
        return <span style={{ fontWeight: 'bold' }}>{Number(value).toFixed(2)}</span>;
      },
    },
    {
      title: '看涨融资利率',
      dataIndex: 'call_funding_rate_option',
      key: 'call_funding_rate_option',
      width: needsScroll ? 150 : 120,
      align: 'right',
      sorter: true,
      sortOrder: sortBy === 'call_funding_rate' ? (sortOrder === 'asc' ? 'ascend' : 'descend') : null,
      render: (_, record) => {
        if (!record.call_funding_rate_option) {
          return <span style={{ color: '#8E8E93' }}>暂无</span>;
        }
        const option = record.call_funding_rate_option;
        const content = renderOptionDetails(option, record.market);
        
        return (
          <Popover
            content={content}
            title="看涨融资利率期权详情"
            trigger="hover"
            placement="left"
            overlayStyle={{ maxWidth: '450px' }}
          >
            <div style={{ cursor: 'pointer' }}>
              {option.profit_percent !== undefined && option.profit_percent !== null ? (
                <div style={{ fontSize: '14px', color: '#52c41a', fontWeight: 'bold' }}>
                  {option.profit_percent.toFixed(2)}%
                </div>
              ) : (
                <span style={{ color: '#8E8E93' }}>暂无数据</span>
              )}
            </div>
          </Popover>
        );
      },
    },
    {
      title: '看跌融资利率',
      dataIndex: 'put_funding_rate_option',
      key: 'put_funding_rate_option',
      width: needsScroll ? 150 : 120,
      align: 'right',
      sorter: true,
      sortOrder: sortBy === 'put_funding_rate' ? (sortOrder === 'asc' ? 'ascend' : 'descend') : null,
      render: (_, record) => {
        if (!record.put_funding_rate_option) {
          return <span style={{ color: '#8E8E93' }}>暂无</span>;
        }
        const option = record.put_funding_rate_option;
        const content = renderOptionDetails(option, record.market);
        
        return (
          <Popover
            content={content}
            title="看跌融资利率期权详情"
            trigger="hover"
            placement="left"
            overlayStyle={{ maxWidth: '450px' }}
          >
            <div style={{ cursor: 'pointer' }}>
              {option.profit_percent !== undefined && option.profit_percent !== null ? (
                <div style={{ fontSize: '14px', color: '#52c41a', fontWeight: 'bold' }}>
                  {option.profit_percent.toFixed(2)}%
                </div>
              ) : (
                <span style={{ color: '#8E8E93' }}>暂无数据</span>
              )}
            </div>
          </Popover>
        );
      },
    },
    {
      title: '看涨/看跌',
      dataIndex: 'call_put_ratio',
      key: 'call_put_ratio',
      width: needsScroll ? 100 : 90,
      align: 'right',
      sorter: true,
      sortOrder: sortBy === 'call_put_ratio' ? (sortOrder === 'asc' ? 'ascend' : 'descend') : null,
      render: (value) => {
        if (value === undefined || value === null || value === 0) {
          return <span style={{ color: '#8E8E93' }}>-</span>;
        }
        return <span>{value.toFixed(2)}</span>;
      },
    },
    {
      title: '裁员人数',
      dataIndex: 'layoff_count',
      key: 'layoff_count',
      width: needsScroll ? 100 : 90,
      align: 'right',
      sorter: true,
      sortOrder: sortBy === 'layoff_count' ? (sortOrder === 'asc' ? 'ascend' : 'descend') : null,
      render: (value) => {
        if (value === undefined || value === null) {
          return <span style={{ color: '#8E8E93' }}>-</span>;
        }
        if (value === 0) {
          return <span style={{ color: '#8E8E93' }}>0</span>;
        }
        return <span style={{ color: '#ff4d4f', fontWeight: 'bold' }}>{value.toLocaleString()}</span>;
      },
    },
    {
      title: '扩张人数',
      dataIndex: 'expansion_count',
      key: 'expansion_count',
      width: needsScroll ? 100 : 90,
      align: 'right',
      sorter: true,
      sortOrder: sortBy === 'expansion_count' ? (sortOrder === 'asc' ? 'ascend' : 'descend') : null,
      render: (value) => {
        if (value === undefined || value === null) {
          return <span style={{ color: '#8E8E93' }}>-</span>;
        }
        if (value === 0) {
          return <span style={{ color: '#8E8E93' }}>0</span>;
        }
        return <span style={{ color: '#52c41a', fontWeight: 'bold' }}>{value.toLocaleString()}</span>;
      },
    },
    {
      title: '回购金额',
      dataIndex: 'buyback_amount',
      key: 'buyback_amount',
      width: needsScroll ? 120 : 100,
      align: 'right',
      ellipsis: true,
      render: (value) => {
        if (value === undefined || value === null || value === '') {
          return <span style={{ color: '#8E8E93' }}>-</span>;
        }
        return <span style={{ color: '#1677ff', fontWeight: 'bold' }}>{value}</span>;
      },
    },
  ];

  return (
    <div className="equation-tab-page">
      <Card 
        className="equation-table-card"
        title="指标排序" 
        style={{ 
          marginBottom: 0,
          borderRadius: '8px',
          overflow: 'hidden'
        }}
        styles={{
          body: {
            padding: '12px'
          }
        }}
        extra={
          <Select
            value={sortBy}
            onChange={handleSortChange}
            placeholder="排序方式"
            style={{ width: 180 }}
            allowClear
          >
            <Option value="call_funding_rate">按看涨融资利率排序</Option>
            <Option value="put_funding_rate">按看跌融资利率排序</Option>
            <Option value="call_put_ratio">按看涨/看跌排序</Option>
            <Option value="eps_yoy_change">按同比增长排序</Option>
            <Option value="deduct_net_asset_pe">按扣净市盈率排序</Option>
            <Option value="layoff_count">按裁员人数排序</Option>
            <Option value="expansion_count">按扩张人数排序</Option>
          </Select>
        }
      >
        <div style={{ marginBottom: 16 }}>
          <AutoComplete
            options={searchOptions}
            onSearch={handleSearch}
            onSelect={handleSelect}
            placeholder="请输入股票代码或名称进行搜索"
            loading={searchLoading}
            style={{ width: '100%' }}
            value={searchValue}
            onChange={setSearchValue}
            allowClear
            onClear={() => {
              setSelectedStockSymbol('');
              setSearchValue('');
              setPage(1);
            }}
          />
          {selectedStockSymbol && (
            <div style={{ marginTop: 8, fontSize: '12px', color: '#8E8E93' }}>
              已筛选：{selectedStockSymbol}
            </div>
          )}
        </div>
        <Table
          columns={columns}
          dataSource={stockOptions}
          rowKey="symbol"
          loading={loading}
          pagination={false}
          scroll={{ x: 'max-content' }}
          onChange={(pagination, filters, sorter) => {
            // 处理表格排序（当用户点击列头排序时，触发后端排序）
            const fieldToSortBy = {
              call_funding_rate_option: 'call_funding_rate',
              put_funding_rate_option: 'put_funding_rate',
              call_put_ratio: 'call_put_ratio',
              eps_yoy_change: 'eps_yoy_change',
              deduct_net_asset_pe: 'deduct_net_asset_pe',
              layoff_count: 'layoff_count',
              expansion_count: 'expansion_count',
            };
            if (sorter && sorter.field && fieldToSortBy[sorter.field]) {
              const nextSortBy = fieldToSortBy[sorter.field];
              if (sortBy === nextSortBy && sorter.order) {
                setSortOrder(sorter.order === 'ascend' ? 'asc' : 'desc');
              } else if (sorter.order) {
                setSortBy(nextSortBy);
                setSortOrder(sorter.order === 'ascend' ? 'asc' : 'desc');
              } else {
                setSortBy('');
                setSortOrder('desc');
              }
              setPage(1);
            } else if (sorter && !sorter.order) {
              setSortBy('');
              setSortOrder('desc');
              setPage(1);
            }
          }}
        />
        <div style={{ marginTop: 16, textAlign: 'right' }}>
          <Pagination
            current={page}
            pageSize={pageSize}
            total={total}
            onChange={handlePageChange}
            showSizeChanger={false}
            showTotal={(total) => `共 ${total} 条`}
          />
        </div>
      </Card>
    </div>
  );
}

export default OptionRate;

