import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Button, Card, DatePicker, Input, Space, Switch, Table, Tag, message } from 'antd';
import { ArrowLeftOutlined, ReloadOutlined, RightOutlined, SyncOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import dayjs from 'dayjs';
import request from '../utils/request';
import PryBoardDailyChart from '../components/PryBoardDailyChart';

const PRY_BOARD_MONTH_MIN_WEEK_DAYS = 2;
const PRY_BOARD_LOOKBACK_DAYS = 50;
const PRY_BOARD_MIN_DROP_FROM_HIGH = 0.30;
const PRY_BOARD_SOURCE_HINT =
  `两融标的（东财）· 新浪/腾讯/东财轮流行情 · 每 5 分钟扫描 · 连续达标 >6 分钟 · 周内累计 ≥${PRY_BOARD_MONTH_MIN_WEEK_DAYS} 天 · 近 ${PRY_BOARD_LOOKBACK_DAYS} 日最高点跌幅 ≥${PRY_BOARD_MIN_DROP_FROM_HIGH * 100}%`;

function defaultChartStart() {
  return dayjs().subtract(30, 'day').format('YYYY-MM-DD');
}

function formatTime(value) {
  if (!value) return '-';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return value;
  return d.toLocaleString('zh-CN', { hour12: false });
}

function formatDate(value) {
  if (!value) return '-';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return String(value).slice(0, 10);
  return d.toLocaleDateString('zh-CN').replace(/\//g, '-');
}

function formatPct(v) {
  if (v == null || Number.isNaN(Number(v))) return '-';
  return `${(Number(v) * 100).toFixed(2)}%`;
}

function renderWeekPryDays(_, row) {
  const days = row?.consecutive_days;
  if (!days || days <= 0) return '-';
  if (days === 1) return <Tag>1</Tag>;
  if (days <= 2) return <Tag color="processing">{days}</Tag>;
  if (days <= 4) return <Tag color="warning">{days}</Tag>;
  return <Tag color="error">{days}</Tag>;
}

function PryBoardStocks() {
  const navigate = useNavigate();
  const [pushEnabled, setPushEnabled] = useState(false);
  const [pushSaving, setPushSaving] = useState(false);

  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);
  const [latestPrices, setLatestPrices] = useState({});
  const [lookbackHigh, setLookbackHigh] = useState({});
  const [dropFromHighPct, setDropFromHighPct] = useState({});
  const [priceMetricsReady, setPriceMetricsReady] = useState(false);
  const [latestLoading, setLatestLoading] = useState(false);

  const [chartStartDate, setChartStartDate] = useState(defaultChartStart);
  const [chartRange, setChartRange] = useState({ start: '', end: '' });
  const [chartPoints, setChartPoints] = useState([]);
  const [chartLoading, setChartLoading] = useState(false);

  const fetchMonthHits = async () => {
    setLoading(true);
    try {
      const res = await request(
        `/api/subscribe/pry-board/month-hits?min_consecutive_days=${PRY_BOARD_MONTH_MIN_WEEK_DAYS}`,
        { method: 'GET' },
      );
      const rows = res?.data?.list;
      setItems(Array.isArray(rows) ? rows : []);
    } catch (e) {
      message.error(e?.message || '加载月内达标数据失败');
    } finally {
      setLoading(false);
    }
  };

  const fetchLatestPrices = useCallback(async () => {
    if (items.length === 0) {
      setLatestPrices({});
      setLookbackHigh({});
      setDropFromHighPct({});
      setPriceMetricsReady(false);
      return;
    }
    setLatestLoading(true);
    setPriceMetricsReady(false);
    try {
      const codes = items.map((it) => it.code).filter(Boolean);
      if (codes.length === 0) return;
      const res = await request(
        `/api/subscribe/pry-board/latest-prices?codes=${codes.join(',')}`,
        { method: 'GET' },
      );
      setLatestPrices(res?.data?.prices || {});
      setLookbackHigh(res?.data?.lookback_high || {});
      setDropFromHighPct(res?.data?.drop_from_high_pct || {});
      setPriceMetricsReady(true);
    } catch (_) {
      setLatestPrices({});
      setLookbackHigh({});
      setDropFromHighPct({});
      setPriceMetricsReady(false);
    } finally {
      setLatestLoading(false);
    }
  }, [items]);

  const displayItems = useMemo(() => {
    if (!priceMetricsReady) {
      return [];
    }
    return items.filter((row) => {
      const drop = dropFromHighPct[row.code];
      const price = latestPrices[row.code];
      const high = lookbackHigh[row.code];
      if (drop == null || price == null || high == null) {
        return false;
      }
      return Number(drop) >= PRY_BOARD_MIN_DROP_FROM_HIGH;
    });
  }, [items, priceMetricsReady, dropFromHighPct, latestPrices, lookbackHigh]);

  const fetchDailyChart = useCallback(async (startDate) => {
    if (!startDate) return;
    setChartLoading(true);
    try {
      const res = await request(
        `/api/subscribe/pry-board/history-daily?start_date=${encodeURIComponent(startDate)}`,
        { method: 'GET' },
      );
      if (res?.code === 200 && res.data) {
        setChartPoints(Array.isArray(res.data.points) ? res.data.points : []);
        setChartRange({
          start: res.data.start_date || startDate,
          end: res.data.end_date || '',
        });
      } else {
        message.error(res?.message || '加载图表失败');
        setChartPoints([]);
      }
    } catch (e) {
      message.error(e?.message || '加载图表失败');
      setChartPoints([]);
    } finally {
      setChartLoading(false);
    }
  }, []);

  const fetchPushEnabled = async () => {
    try {
      const res = await request('/api/subscribe/pry-board/push-enabled', { method: 'GET' });
      if (typeof res?.data?.push_enabled === 'boolean') {
        setPushEnabled(res.data.push_enabled);
      }
    } catch (_) {
      // ignore
    }
  };

  const onPushToggle = async (checked) => {
    setPushSaving(true);
    const prev = pushEnabled;
    setPushEnabled(checked);
    try {
      const res = await request('/api/subscribe/pry-board/push-enabled', {
        method: 'PUT',
        body: JSON.stringify({ enabled: checked }),
      });
      if (typeof res?.data?.push_enabled === 'boolean') {
        setPushEnabled(res.data.push_enabled);
      }
      message.success(checked ? '已开启 Bark 推送' : '已关闭推送，仅页面展示');
    } catch (e) {
      setPushEnabled(prev);
      message.error(e?.message || '保存推送开关失败');
    } finally {
      setPushSaving(false);
    }
  };

  useEffect(() => {
    fetchMonthHits();
    fetchPushEnabled();
  }, []);

  useEffect(() => {
    if (items.length > 0) {
      fetchLatestPrices();
    } else {
      setLatestPrices({});
      setLookbackHigh({});
      setDropFromHighPct({});
      setPriceMetricsReady(false);
    }
  }, [items, fetchLatestPrices]);

  useEffect(() => {
    fetchDailyChart(chartStartDate);
  }, [chartStartDate, fetchDailyChart]);

  const columns = [
    { title: '交易日', dataIndex: 'trade_date', key: 'trade_date', width: 110, render: formatDate },
    { title: '代码', dataIndex: 'code', key: 'code', width: 110 },
    { title: '名称', dataIndex: 'name', key: 'name', width: 120, ellipsis: true },
    {
      title: '昨收',
      dataIndex: 'prev_close',
      key: 'prev_close',
      width: 90,
      render: (v) => (v != null ? Number(v).toFixed(2) : '-'),
    },
    {
      title: '跌停价',
      dataIndex: 'limit_down',
      key: 'limit_down',
      width: 90,
      render: (v) => (v != null ? Number(v).toFixed(2) : '-'),
    },
    {
      title: '日内最低',
      dataIndex: 'day_low',
      key: 'day_low',
      width: 90,
      render: (v) => (v != null ? Number(v).toFixed(2) : '-'),
    },
    {
      title: '入库时价',
      dataIndex: 'last_price',
      key: 'last_price',
      width: 90,
      render: (v) => (v != null ? Number(v).toFixed(2) : '-'),
    },
    {
      title: '股票最新价',
      key: 'latest_price',
      width: 90,
      render: (_, row) => {
        const p = latestPrices[row.code];
        if (p == null) return '-';
        return <span style={{ color: '#1677ff' }}>{Number(p).toFixed(2)}</span>;
      },
    },
    {
      title: '50日最高',
      key: 'lookback_high',
      width: 90,
      render: (_, row) => {
        const v = lookbackHigh[row.code];
        return v != null ? Number(v).toFixed(2) : '-';
      },
    },
    {
      title: '距高点跌幅',
      key: 'drop_from_high_pct',
      width: 100,
      render: (_, row) => {
        const v = dropFromHighPct[row.code];
        if (v == null) return '-';
        const pct = Number(v) * 100;
        const color = pct >= PRY_BOARD_MIN_DROP_FROM_HIGH * 100 ? '#cf1322' : '#8c8c8c';
        return <span style={{ color, fontWeight: 600 }}>{pct.toFixed(2)}%</span>;
      },
    },
    { title: '距跌停', dataIndex: 'near_pct', key: 'near_pct', width: 90, render: formatPct },
    { title: '反弹', dataIndex: 'rebound_pct', key: 'rebound_pct', width: 90, render: formatPct },
    { title: '周内翘板天数', key: 'consecutive_days', width: 110, render: renderWeekPryDays },
    { title: '发现时间', dataIndex: 'detected_at', key: 'detected_at', width: 170, render: formatTime },
  ];

  return (
    <div className="equation-tab-page">
      <div style={{
        position: 'sticky',
        top: 0,
        zIndex: 1000,
        background: '#fff',
        padding: '16px',
        borderBottom: '1px solid #E5E5EA',
        display: 'grid',
        gridTemplateColumns: '1fr auto 1fr',
        alignItems: 'center',
        gap: 8,
      }}
      >
        <Button type="text" icon={<ArrowLeftOutlined />} onClick={() => navigate('/subscribe-stock')} style={{ justifySelf: 'start' }}>
          返回
        </Button>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, justifySelf: 'center' }}>
          <span style={{ color: '#8E8E93', fontSize: 12 }}>Bark 推送</span>
          <Switch
            checked={pushEnabled}
            loading={pushSaving}
            onChange={onPushToggle}
            checkedChildren="开"
            unCheckedChildren="关"
          />
        </div>
        <Button
          type="text"
          onClick={() => navigate('/pry-board/history')}
          style={{ display: 'flex', alignItems: 'center', gap: '4px', justifySelf: 'end' }}
        >
          历史数据
          <RightOutlined />
        </Button>
      </div>

      <Card
        title="月内翘板达标股票"
        style={{
          margin: '16px',
          marginTop: 24,
          borderRadius: 14,
          border: 'none',
          boxShadow: '0 2px 8px rgba(0,0,0,0.06)',
          overflow: 'hidden',
        }}
        bodyStyle={{ padding: 12, overflowX: 'auto' }}
        extra={(
          <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
            <span style={{ color: '#8E8E93', fontSize: 12 }}>
              周内累计 ≥{PRY_BOARD_MONTH_MIN_WEEK_DAYS} 天 · 近 {PRY_BOARD_LOOKBACK_DAYS} 日跌幅 ≥{PRY_BOARD_MIN_DROP_FROM_HIGH * 100}%
            </span>
            <Button type="text" icon={<SyncOutlined />} onClick={fetchLatestPrices} loading={latestLoading}>
              查询最新价
            </Button>
            <Button type="text" icon={<ReloadOutlined />} onClick={fetchMonthHits} loading={loading}>
              刷新
            </Button>
          </div>
        )}
      >
        <Table
          columns={columns}
          dataSource={displayItems}
          rowKey="id"
          loading={loading || latestLoading}
          size="small"
          scroll={{ x: 'max-content' }}
          locale={{
            emptyText: priceMetricsReady
              ? `暂无满足「周内累计 ≥${PRY_BOARD_MONTH_MIN_WEEK_DAYS} 天且近 ${PRY_BOARD_LOOKBACK_DAYS} 日最高点跌幅 ≥${PRY_BOARD_MIN_DROP_FROM_HIGH * 100}%」的记录`
              : '正在加载行情并计算近 50 日最高价…',
          }}
          pagination={{
            pageSize: 20,
            showSizeChanger: true,
            showTotal: (total) => {
              if (!priceMetricsReady) {
                return `原始 ${items.length} 条，筛选中…`;
              }
              return `展示 ${total} 条（原始 ${items.length} 条，已过滤跌幅 <${PRY_BOARD_MIN_DROP_FROM_HIGH * 100}%）`;
            },
          }}
        />
      </Card>

      <Card
        title="撬板按日统计"
        style={{
          margin: '16px',
          marginTop: 8,
          borderRadius: 14,
          border: 'none',
          boxShadow: '0 2px 8px rgba(0,0,0,0.06)',
          overflow: 'hidden',
        }}
        bodyStyle={{ padding: 16, overflowX: 'auto' }}
        extra={
          <Space wrap>
            <span style={{ color: '#8E8E93', fontSize: 12 }}>开始时间</span>
            <DatePicker
              value={chartStartDate ? dayjs(chartStartDate) : null}
              allowClear={false}
              format="YYYY-MM-DD"
              disabledDate={(current) => {
                if (!current) return false;
                const today = dayjs().endOf('day');
                const min = dayjs().subtract(365, 'day').startOf('day');
                return current.isAfter(today) || current.isBefore(min);
              }}
              onChange={(date) => {
                if (date && date.format) {
                  setChartStartDate(date.format('YYYY-MM-DD'));
                }
              }}
            />
            <span style={{ color: '#8E8E93', fontSize: 12 }}>结束时间</span>
            <Input
              value={chartRange.end || '-'}
              readOnly
              style={{
                width: 120,
                color: '#1C1C1E',
                backgroundColor: '#F2F2F7',
                border: 'none',
                borderRadius: 8,
                cursor: 'default',
              }}
            />
            <Button type="text" icon={<ReloadOutlined />} onClick={() => fetchDailyChart(chartStartDate)} loading={chartLoading}>
              刷新
            </Button>
          </Space>
        }
      >
        <PryBoardDailyChart data={chartPoints} width={760} height={280} />
      </Card>

      <div style={{
        textAlign: 'center',
        padding: '8px 16px 24px',
        color: '#8E8E93',
        fontSize: 12,
      }}
      >
        {PRY_BOARD_SOURCE_HINT}
      </div>
    </div>
  );
}

export default PryBoardStocks;
