import React, { useEffect, useRef } from 'react';

// Apple 风格日柱：系统蓝圆角柱 + 浅分隔网格，对齐 App.css 色板。
// data: [{ date: 'YYYY-MM-DD', count: number }]
const FONT =
  '-apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif';

function roundRect(ctx, x, y, w, h, r) {
  const radius = Math.max(0, Math.min(r, w / 2, h / 2));
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + w, y, x + w, y + h, radius);
  ctx.arcTo(x + w, y + h, x, y + h, radius);
  ctx.arcTo(x, y + h, x, y, radius);
  ctx.arcTo(x, y, x + w, y, radius);
  ctx.closePath();
}

function PryBoardDailyChart({ data, width = 760, height = 280 }) {
  const canvasRef = useRef(null);

  useEffect(() => {
    if (!data || data.length === 0) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;

    canvas.width = width * dpr;
    canvas.height = height * dpr;
    canvas.style.width = `${width}px`;
    canvas.style.height = `${height}px`;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const padding = { top: 32, right: 16, bottom: 44, left: 40 };
    const chartWidth = width - padding.left - padding.right;
    const chartHeight = height - padding.top - padding.bottom;

    // 透明底，让外层白卡片透出，避免硬白块
    ctx.clearRect(0, 0, width, height);

    const maxCount = Math.max(1, ...data.map((d) => Number(d.count) || 0));
    const gridLines = 4;

    // 分隔线：Apple separator
    ctx.strokeStyle = 'rgba(60, 60, 67, 0.12)';
    ctx.lineWidth = 0.5;
    ctx.fillStyle = '#8E8E93';
    ctx.font = `500 11px ${FONT}`;
    ctx.textAlign = 'right';

    for (let i = 0; i <= gridLines; i++) {
      const y = padding.top + (chartHeight / gridLines) * i;
      ctx.beginPath();
      ctx.moveTo(padding.left, y);
      ctx.lineTo(width - padding.right, y);
      ctx.stroke();
      const val = Math.round(maxCount - (maxCount / gridLines) * i);
      ctx.fillText(String(val), padding.left - 8, y + 4);
    }

    const gap = chartWidth / data.length;
    const barWidth = Math.max(3, Math.min(18, gap * 0.55));
    const labelStep = Math.max(1, Math.ceil(data.length / 8));
    const barRadius = Math.min(6, barWidth / 2);

    data.forEach((d, i) => {
      const count = Number(d.count) || 0;
      const slotCenter = padding.left + gap * i + gap / 2;

      if (count > 0) {
        const barH = Math.max(4, (count / maxCount) * chartHeight);
        const x = slotCenter - barWidth / 2;
        const y = padding.top + chartHeight - barH;

        const grad = ctx.createLinearGradient(x, y, x, y + barH);
        grad.addColorStop(0, '#64B5F6');
        grad.addColorStop(1, '#007AFF');
        ctx.fillStyle = grad;
        roundRect(ctx, x, y, barWidth, barH, barRadius);
        ctx.fill();
      }

      if (i % labelStep === 0 || i === data.length - 1) {
        ctx.fillStyle = '#AEAEB2';
        ctx.font = `400 10px ${FONT}`;
        ctx.textAlign = 'center';
        const label = String(d.date || '').slice(5); // MM-DD
        ctx.fillText(label, slotCenter, height - padding.bottom + 18);
      }
    });

    ctx.fillStyle = '#1C1C1E';
    ctx.font = `600 13px ${FONT}`;
    ctx.textAlign = 'left';
    ctx.fillText('每日撬板命中数', padding.left, 18);
  }, [data, width, height]);

  if (!data || data.length === 0) {
    return (
      <div style={{ textAlign: 'center', padding: 40, color: '#8E8E93', fontFamily: FONT, fontSize: 14 }}>
        暂无图表数据
      </div>
    );
  }

  return (
    <canvas
      ref={canvasRef}
      style={{ display: 'block', margin: '0 auto', maxWidth: '100%' }}
    />
  );
}

export default PryBoardDailyChart;
