function fmtPct(pct) {
  const sign = pct >= 0 ? '+' : '';
  return sign + pct.toFixed(1) + '%';
}

function MetricBox({ icon, label, value, sub, color }) {
  return (
    <div style={{
      flex: '1 1 0',
      minWidth: 0,
      display: 'flex',
      flexDirection: 'column',
      gap: '2px',
      padding: '12px 10px',
      borderRadius: '12px',
      background: '#F2F2F7',
    }}>
      <span style={{ fontSize: '11px', color: '#8E8E93', display: 'flex', alignItems: 'center', gap: '4px' }}>
        {icon}{label}
      </span>
      <span style={{ fontSize: '18px', fontWeight: 700, color: color || '#1C1C1E', lineHeight: 1.3 }}>
        {value}
      </span>
      {sub && <span style={{ fontSize: '11px', color: '#AEAEB2' }}>{sub}</span>}
    </div>
  );
}

function TimelineNode({ label, date, price, close, isLow }) {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '6px', flex: '1 1 0', minWidth: 0 }}>
      <Tag color={isLow ? 'green' : 'red'} style={{ margin: 0, fontSize: '11px', fontWeight: 600 }}>
        {label}
      </Tag>
      <div style={{
        width: '12px',
        height: '12px',
        borderRadius: '50%',
        background: isLow ? '#34C759' : '#FF3B30',
        border: '3px solid #fff',
        boxShadow: '0 0 0 2px ' + (isLow ? '#34C759' : '#FF3B30'),
        flexShrink: 0,
      }} />
      <span style={{ fontSize: '12px', color: '#8E8E93', whiteSpace: 'nowrap' }}>{date}</span>
      <span style={{ fontSize: '17px', fontWeight: 700, color: '#1C1C1E' }}>{price}</span>
      {close != null && (
        <span style={{ fontSize: '11px', color: '#AEAEB2' }}>收盘 {close}</span>
      )}
    </div>
  );
}

function StockCard({ stock }) {
  return (
    <Card
      style={{
        marginBottom: '16px',
        borderRadius: '16px',
        border: 'none',
        boxShadow: '0 1px 4px rgba(0,0,0,0.06)',
      }}
      bodyStyle={{ padding: '20px 16px' }}
    >
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '16px' }}>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: '8px' }}>
          <span style={{
            width: '4px',
            height: '20px',
            borderRadius: '2px',
            background: stock.color,
            display: 'inline-block',
            marginRight: '4px',
          }} />
          <Title level={5} style={{ margin: 0, fontWeight: 700 }}>{stock.name}</Title>
          <Text style={{ fontSize: '13px', color: '#8E8E93' }}>{stock.code}</Text>
        </div>
        <Tag style={{ borderRadius: '8px', fontSize: '11px' }}>{stock.market}</Tag>
      </div>

      <div style={{
        display: 'flex',
        alignItems: 'flex-start',
        justifyContent: 'space-between',
        padding: '8px 4px 20px',
        position: 'relative',
      }}>
        <div style={{
          position: 'absolute',
          top: '38px',
          left: '16%',
          right: '16%',
          height: '3px',
          background: 'linear-gradient(90deg, #34C759 0%, #FF3B30 100%)',
          borderRadius: '2px',
          opacity: 0.3,
        }} />
        <TimelineNode
          label="阶段最低"
          date={stock.low.date}
          price={stock.low.price}
          close={stock.low.close}
          isLow
        />
        <TimelineNode
          label="阶段最高"
          date={stock.stageHigh.date}
          price={stock.stageHigh.price}
          close={stock.stageHigh.close}
        />
      </div>

      <div style={{ display: 'flex', gap: '8px', marginBottom: '16px' }}>
        <MetricBox
          icon={<FallOutlined />}
          label="距前高回撤"
          value={fmtPct(stock.declinePct)}
          sub={'前高 ' + stock.priorHigh.price + ' (' + stock.priorHigh.date + ')'}
          color="#34C759"
        />
        <MetricBox
          icon={<RiseOutlined />}
          label="低点反弹"
          value={fmtPct(stock.reboundPct)}
          sub={'涨幅 ' + (stock.stageHigh.price - stock.low.price).toFixed(2)}
          color="#FF3B30"
        />
        <MetricBox
          icon={<ClockCircleOutlined />}
          label="反弹历时"
          value={stock.daysToHigh + ' 天'}
          sub={stock.bestOptionTermEn}
        />
      </div>

      <div style={{
        background: 'linear-gradient(135deg, #FFF8E1 0%, #FFF3C4 100%)',
        borderRadius: '12px',
        padding: '14px 16px',
        marginBottom: '14px',
        border: '1px solid #FFE082',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '4px' }}>
          <ClockCircleOutlined style={{ color: '#F57F17', fontSize: '14px' }} />
          <Text style={{ fontSize: '13px', fontWeight: 600, color: '#F57F17' }}>最佳期权期限</Text>
        </div>
        <Text style={{ fontSize: '16px', fontWeight: 700, color: '#E65100' }}>
          {stock.bestOptionTerm}
        </Text>
        <div style={{ fontSize: '12px', color: '#9E7B00', marginTop: '4px' }}>
          从最低点买入 Call，到期日匹配反弹到阶段高点的时间
        </div>
      </div>

      <Paragraph style={{ fontSize: '13px', color: '#6B6B6B', lineHeight: 1.7, marginBottom: 0 }}>
        {stock.context}
      </Paragraph>
    </Card>
  );
}

