import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Card, Form, Button, Table, AutoComplete, message, Input, Tooltip, Select, Switch } from 'antd';
import { PlusOutlined, DeleteOutlined, SaveOutlined, QuestionCircleOutlined, RightOutlined } from '@ant-design/icons';
import { useNavigate, useSearchParams } from 'react-router-dom';
import request from '../utils/request';

const DEFAULT_MARKET = 'HKNewStock';
const SUBSCRIBE_STOCKS_PAGE_SIZE = 15;
/** USDT/USD 现货价接近 1，需比股票更高的展示精度 */
const USDTUSD_SYMBOL = 'USDTUSD';

function formatSubscribeCurrentPrice(value, symbol) {
  const n = Number(value);
  if (!Number.isFinite(n)) {
    return null;
  }
  if (symbol === USDTUSD_SYMBOL) {
    return n.toFixed(4);
  }
  return n.toFixed(2);
}

// 监控跌破价格编辑组件（输入框与「已满配/保存」左对齐）
const MonitorDropPriceEditor = ({ record, onSave }) => {
  const [editingPrice, setEditingPrice] = useState(record.monitor_drop_price || 0);
  const [saving, setSaving] = useState(false);
  useEffect(() => {
    setEditingPrice(record.monitor_drop_price || 0);
  }, [record.monitor_drop_price]);

  const handleSave = async () => {
    try {
      setSaving(true);
      const price = parseFloat(editingPrice);
      const requestBody = {
        symbol: record.symbol,
      };
      // 只有当价格存在且大于0时才添加monitor_drop_price字段
      if (price && price > 0) {
        requestBody.monitor_drop_price = price;
      } else {
        // 如果价格为0或空，设置-monitor_drop_price为0（表示清除）
        requestBody.monitor_drop_price = 0;
      }
      const response = await request('/api/subscribe/stocks/monitor-drop-price', {
        method: 'PUT',
        body: JSON.stringify(requestBody),
      });

      if (response.code === 200) {
        message.success('保存监控跌破价格成功');
        if (onSave) {
          onSave();
        }
      } else {
        message.error(response.message || '保存监控跌破价格失败');
      }
    } catch (error) {
      console.error('保存监控跌破价格失败:', error);
      message.error('保存监控跌破价格失败，请稍后重试');
    } finally {
      setSaving(false);
    }
  };

  const handleSetFullPosition = async () => {
    setEditingPrice('0.01');
    try {
      setSaving(true);
      const response = await request('/api/subscribe/stocks/monitor-drop-price', {
        method: 'PUT',
        body: JSON.stringify({
          symbol: record.symbol,
          monitor_drop_price: 0.01,
        }),
      });

      if (response.code === 200) {
        message.success('已设置为满配价 0.01');
        if (onSave) {
          onSave();
        }
      } else {
        message.error(response.message || '设置满配价失败');
      }
    } catch (error) {
      console.error('设置满配价失败:', error);
      message.error('设置满配价失败，请稍后重试');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="subscribe-list-number-input" style={{ display: 'flex', flexDirection: 'column', alignItems: 'stretch', width: '100%' }}>
      <Input
        type="number"
        value={editingPrice || ''}
        onChange={(e) => setEditingPrice(e.target.value)}
        step="0.01"
        min="0"
        style={{ width: '65px', marginBottom: '4px' }}
        onPressEnter={handleSave}
      />
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%' }}>
        <Button
          type="link"
          size="small"
          onClick={handleSetFullPosition}
          loading={saving}
          style={{ padding: 0, margin: 0 }}
        >
          已满配
        </Button>
        <Button
          type="link"
          size="small"
          onClick={handleSave}
          loading={saving}
          style={{ padding: 0, margin: 0 }}
        >
          保存
        </Button>
      </div>
    </div>
  );
};

// 涨过自动卖出数量（整数，0 表示不触发）
const SellQtyEditor = ({ record, onSave }) => {
  const [editingQty, setEditingQty] = useState(record.sell_qty ?? 0);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    setEditingQty(record.sell_qty ?? 0);
  }, [record.sell_qty]);

  const handleSave = async () => {
    const qty = parseInt(editingQty, 10);
    if (Number.isNaN(qty) || qty < 0) {
      message.error('卖出数量须为非负整数');
      return;
    }
    try {
      setSaving(true);
      const response = await request('/api/subscribe/stocks/sell-qty', {
        method: 'PUT',
        body: JSON.stringify({
          symbol: record.symbol,
          sell_qty: qty,
        }),
      });
      if (response.code === 200) {
        message.success('保存卖出数量成功');
        if (onSave) onSave();
      } else {
        message.error(response.message || '保存卖出数量失败');
      }
    } catch (error) {
      console.error('保存卖出数量失败:', error);
      message.error('保存卖出数量失败，请稍后重试');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="subscribe-list-number-input" style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end' }}>
      <Input
        type="number"
        value={editingQty === 0 ? '' : editingQty}
        onChange={(e) => setEditingQty(e.target.value)}
        step="1"
        min="0"
        precision={0}
        style={{ width: '65px', marginBottom: '4px' }}
        onPressEnter={handleSave}
        placeholder="0"
      />
      <Button type="link" size="small" onClick={handleSave} loading={saving} style={{ padding: '0 4px' }}>
        保存
      </Button>
    </div>
  );
};

