// 低买 / 高卖开关：默认低买(L1-L4)，开启为高卖(S1-S4)
const HighSellModeSwitch = ({ record, onSave }) => {
  const [saving, setSaving] = useState(false);

  const handleChange = async (checked) => {
    try {
      setSaving(true);
      const response = await request('/api/subscribe/stocks/high-sell', {
        method: 'PUT',
        body: JSON.stringify({
          symbol: record.symbol,
          high_sell: checked,
        }),
      });
      if (response.code === 200) {
        message.success(checked ? '已切换为高卖（S1-S4）' : '已切换为低买（L1-L4）');
        if (onSave) onSave();
      } else {
        message.error(response.message || '切换策略模式失败');
      }
    } catch (error) {
      console.error('切换策略模式失败:', error);
      message.error('切换策略模式失败，请稍后重试');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Switch
      checked={!!record.high_sell}
      loading={saving}
      onChange={handleChange}
      checkedChildren="高卖"
      unCheckedChildren="低买"
      size="small"
    />
  );
};

function formatPeRatio(value) {
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) {
    return '-';
  }
  return n.toFixed(2);
}

function SubscribeStock() {
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const [form] = Form.useForm();
  const [options, setOptions] = useState([]);
  const [selectedStocks, setSelectedStocks] = useState([]);
  const [loading, setLoading] = useState(false);
  const [subscribeStocks, setSubscribeStocks] = useState([]);
  const [loadingStocks, setLoadingStocks] = useState(false);
  const [listPage, setListPage] = useState(1);
  const [listTotal, setListTotal] = useState(0);
  const [selectedRowKeys, setSelectedRowKeys] = useState([]);
  const [pushKey, setPushKey] = useState('');
  const [loadingPushKey, setLoadingPushKey] = useState(false);
  const [barkKey, setBarkKey] = useState('');
  const [loadingBarkKey, setLoadingBarkKey] = useState(false);
  const [activePushType, setActivePushType] = useState('bark'); // bark 或 pushdeer，默认 Bark
  const [windowWidth, setWindowWidth] = useState(window.innerWidth);
  const hasLoadedRef = useRef(false); // 使用ref防止重复加载
  const listPageRef = useRef(1);
  
  // 获取图片路径，处理可能的base path
  const getImagePath = () => {
    const publicUrl = process.env.PUBLIC_URL || '';
    if (!publicUrl && window.location.pathname.includes('/equation')) {
      return '/equation/images/pushdeer-qrcode.png';
    }
    return `${publicUrl}/images/pushdeer-qrcode.png`;
  };
  // Bark 说明图（App Store 二维码）
  const getBarkImagePath = () => {
    const publicUrl = process.env.PUBLIC_URL || '';
    if (!publicUrl && window.location.pathname.includes('/equation')) {
      return '/equation/images/bark-app-qrcode.png';
    }
    return `${publicUrl}/images/bark-app-qrcode.png`;
  };

  // 监听窗口大小变化
  useEffect(() => {
    const handleResize = () => {
      setWindowWidth(window.innerWidth);
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // 加载订阅股票列表（服务端分页，每页 15 条）
  const loadSubscribeStocks = useCallback(async (page) => {
    const targetPage = page ?? listPageRef.current ?? 1;
    try {
      setLoadingStocks(true);
      const fetchPage = async (p) => {
        const params = new URLSearchParams({
          page: String(p),
          page_size: String(SUBSCRIBE_STOCKS_PAGE_SIZE),
        });
        const response = await request(`/api/subscribe/stocks?${params.toString()}`, {
          method: 'GET',
        });
        if (response.code !== 200 || !response.data) {
          return { rows: [], total: 0, page: p };
        }
        return {
          rows: Array.isArray(response.data.list) ? response.data.list : [],
          total: Number(response.data.total) || 0,
          page: Number(response.data.page) > 0 ? Number(response.data.page) : p,
        };
      };

      let { rows, total, page: respPage } = await fetchPage(targetPage);
      if (rows.length === 0 && total > 0 && respPage > 1) {
        ({ rows, total, page: respPage } = await fetchPage(respPage - 1));
      }
      setSubscribeStocks(rows);
      setListTotal(total);
      setListPage(respPage);
      listPageRef.current = respPage;
    } catch (error) {
      console.error('加载订阅股票失败:', error);
      message.error('加载订阅股票失败，请稍后重试');
      setSubscribeStocks([]);
      setListTotal(0);
    } finally {
      setLoadingStocks(false);
    }
  }, []);

  // 组件加载时：如果是从监控跌破的推送链接进入（URL 含 symbol 和 current_price），
  // 先自动触发一次“监控跌破”阈值的保存请求，然后再加载订阅列表和推送 key。
  // 只在首次渲染时执行一次，这里刻意不把 loadSubscribeStocks / searchParams / setSearchParams 放到依赖中
  useEffect(() => {
    // 防止React StrictMode导致的重复请求
    if (hasLoadedRef.current) {
      return;
    }
    hasLoadedRef.current = true;

    const init = async () => {
      try {
        const symbolFromUrl = searchParams.get('symbol');
        const currentPriceFromUrl = searchParams.get('current_price');
        if (symbolFromUrl && currentPriceFromUrl) {
          const price = parseFloat(currentPriceFromUrl);
          if (!Number.isNaN(price) && price > 0) {
            const resp = await request('/api/subscribe/stocks/monitor-drop-price', {
              method: 'PUT',
              body: JSON.stringify({
                symbol: symbolFromUrl,
                monitor_drop_price: price,
              }),
            });
            if (resp && resp.code === 200) {
              message.success('已根据推送链接更新监控跌破阈值');
            } else if (resp) {
              message.error(resp.message || '根据推送链接更新监控跌破阈值失败');
            }
          }
        }
      } catch (error) {
        console.error('根据推送链接更新监控跌破阈值失败:', error);
        message.error('根据推送链接更新监控跌破阈值失败，请稍后重试');
      } finally {
        // 清除 URL 参数，避免后续刷新重复触发
        setSearchParams({});
        // 然后再加载订阅股票列表和推送 key
        loadSubscribeStocks(1);
        loadPushKey();
        loadBarkKey();
      }
    };

    init();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 加载推送key
  const loadPushKey = async () => {
    try {
      const response = await request('/api/subscribe/pushkey', {
        method: 'GET',
      });

      if (response.code === 200 && response.data) {
        setPushKey(response.data.pushkey || '');
      }
    } catch (error) {
      console.error('加载推送key失败:', error);
    }
  };

  // 保存推送key
  const handleSavePushKey = async () => {
    try {
      setLoadingPushKey(true);
      const response = await request('/api/subscribe/pushkey', {
        method: 'POST',
        body: JSON.stringify({
          pushkey: pushKey,
        }),
      });

      if (response.code === 200) {
        message.success('保存推送key成功');
      } else {
        message.error(response.message || '保存推送key失败');
      }
    } catch (error) {
      console.error('保存推送key失败:', error);
      message.error('保存推送key失败，请稍后重试');
    } finally {
      setLoadingPushKey(false);
    }
  };

  // 加载 Bark key
  const loadBarkKey = async () => {
    try {
      const response = await request('/api/subscribe/barkkey', { method: 'GET' });
      if (response.code === 200 && response.data) {
        setBarkKey(response.data.barkkey || '');
      }
    } catch (error) {
      console.error('加载Bark key失败:', error);
    }
  };

  // 保存 Bark key
  const handleSaveBarkKey = async () => {
    try {
      setLoadingBarkKey(true);
      const response = await request('/api/subscribe/barkkey', {
        method: 'POST',
        body: JSON.stringify({ barkkey: barkKey }),
      });
      if (response.code === 200) {
        message.success('保存推送Key (Bark) 成功');
      } else {
        message.error(response.message || '保存Bark key失败');
      }
    } catch (error) {
      console.error('保存Bark key失败:', error);
      message.error('保存Bark key失败，请稍后重试');
    } finally {
      setLoadingBarkKey(false);
    }
  };

  const handleSearch = async (value) => {
    if (!value) {
      setOptions([]);
      return;
    }

    try {
      setLoading(true);
      console.log('Searching for stock:', value);
      const response = await request('/api/stock/search', {
        method: 'POST',
        body: JSON.stringify({ name: value }),
      });

      console.log('Search response:', response);
      if (response.code === 200 && Array.isArray(response.data)) {
        const stockOptions = response.data.map(stock => ({
          value: stock.symbol,
          label: (
            <div>
              <div>{stock.symbol}</div>
              <div style={{ fontSize: '12px', color: '#999' }}>{stock.chinese_name}</div>
            </div>
          ),
          stock: stock
        }));
        setOptions(stockOptions);
      } else {
        console.log('Invalid response format:', response);
        setOptions([]);
        message.error('找不到对应的股票:' + value);
      }
    } catch (error) {
      console.error('搜索股票失败:', error);
      message.error('搜索失败，请稍后重试');
      setOptions([]);
    } finally {
      setLoading(false);
    }
  };

  const handleSelect = async (value, option) => {
    const stock = option.stock;
    if (!selectedStocks.some(s => s.symbol === stock.symbol)) {
      setSelectedStocks([...selectedStocks, {
        ...stock,
        market: stock.market || DEFAULT_MARKET,
        monitor_drop_price: 0,
        monitor_rise_price: 0,
        sell_qty: 0,
      }]);
    }
  };

  // 更新选中股票的监控跌破价格
  const handleUpdateMonitorDropPrice = (symbol, price) => {
    setSelectedStocks(stocks => 
      stocks.map(s => s.symbol === symbol ? { ...s, monitor_drop_price: price } : s)
    );
  };

  // 更新选中股票的监控涨过价格
  const handleUpdateMonitorRisePrice = (symbol, price) => {
    setSelectedStocks(stocks => 
      stocks.map(s => s.symbol === symbol ? { ...s, monitor_rise_price: price } : s)
    );
  };


  const handleRemoveStock = (symbol) => {
    setSelectedStocks(stocks => stocks.filter(stock => stock.symbol !== symbol));
  };

  // 添加订阅股票
  const handleAdd = async () => {
    if (selectedStocks.length === 0) {
      message.warning('请至少添加一只股票');
      return;
    }

    try {
      const response = await request('/api/subscribe/stocks', {
        method: 'POST',
        body: JSON.stringify({
          stock_list: selectedStocks.map(stock => {
            const stockData = {
              symbol: stock.symbol,
              market: stock.market || DEFAULT_MARKET,
            };
            if (stock.monitor_drop_price && stock.monitor_drop_price > 0) {
              stockData.monitor_drop_price = stock.monitor_drop_price;
            }
            if (stock.monitor_rise_price && stock.monitor_rise_price > 0) {
              stockData.monitor_rise_price = stock.monitor_rise_price;
            }
            if (stock.sell_qty != null && stock.sell_qty > 0) {
              stockData.sell_qty = Math.floor(stock.sell_qty);
            }
            return stockData;
          }),
        }),
      });

      if (response.code === 200) {
        message.success('添加订阅股票成功');
        setSelectedStocks([]);
        form.resetFields();
        loadSubscribeStocks(1); // 重新加载订阅股票列表
      } else {
        message.error(response.message || '添加订阅股票失败');
      }
    } catch (error) {
      console.error('添加订阅股票失败:', error);
      message.error('添加订阅股票失败，请稍后重试');
    }
  };

  // 删除订阅股票
  const handleDelete = async () => {
    if (selectedRowKeys.length === 0) {
      message.warning('请至少选择一只股票');
      return;
    }

    try {
      const stocksToDelete = subscribeStocks.filter(stock => selectedRowKeys.includes(stock.symbol));
      const response = await request('/api/subscribe/stocks', {
        method: 'DELETE',
        body: JSON.stringify({
          stock_list: stocksToDelete.map(stock => ({
            symbol: stock.symbol
          })),
        }),
      });

      if (response.code === 200) {
        message.success('删除订阅股票成功');
        setSelectedRowKeys([]);
        loadSubscribeStocks(listPageRef.current);
      } else {
        message.error(response.message || '删除订阅股票失败');
      }
    } catch (error) {
      console.error('删除订阅股票失败:', error);
      message.error('删除订阅股票失败，请稍后重试');
    }
  };

  // 置顶订阅股票
  const handlePin = async (symbol) => {
    try {
      const response = await request('/api/subscribe/stocks/pin', {
        method: 'PUT',
        body: JSON.stringify({
          symbol: symbol,
        }),
      });

      if (response.code === 200) {
        message.success('置顶成功');
        loadSubscribeStocks(1); // 重新加载订阅股票列表
      } else {
        message.error(response.message || '置顶失败');
      }
    } catch (error) {
      console.error('置顶订阅股票失败:', error);
      message.error('置顶失败，请稍后重试');
    }
  };

  // 根据屏幕宽度计算是否启用横向滚动
  // 优化后的列宽总和约1200px（包含所有列和选择框约50px），实际需要约1250px
  // 如果屏幕宽度 >= 1400px（考虑了padding和边距），则不需要滚动
  const needsScroll = windowWidth < 1400;
  const isMobile = windowWidth < 768;
  const nameColumnWidth = isMobile ? 72 : needsScroll ? 88 : 98;
  
  // 优化列宽，使其在大屏幕上更紧凑但保持可读性
  const getColumnWidth = (baseWidth, compactWidth) => {
    return needsScroll ? baseWidth : compactWidth;
  };

  const subscribeColumns = [
    {
      title: '股票名称',
      dataIndex: 'chinese_name',
      key: 'chinese_name',
      width: nameColumnWidth,
      fixed: needsScroll ? 'left' : undefined,
      className: 'subscribe-stock-name-col',
      onCell: () => ({ className: 'subscribe-stock-name-cell' }),
      render: (text, record) => (
        <div className="subscribe-stock-name-wrap">
          <span className="subscribe-stock-name-cn">
            {text || record.symbol}
          </span>
          <span className="subscribe-stock-name-en">
            {record.english_name || record.symbol}
          </span>
        </div>
      ),
    },
    {
      title: '当前价',
      dataIndex: 'current_price',
      key: 'current_price',
      width: getColumnWidth(100, 75),
      align: 'right',
      render: (value, record) => {
        if (value === undefined || value === null || value === 0) {
          return <span style={{ color: '#999' }}>-</span>;
        }
        const formatted = formatSubscribeCurrentPrice(value, record.symbol);
        return <span style={{ fontWeight: 'bold' }}>{formatted}</span>;
      },
    },
    {
      title: (
        <span>
          当日成交量/1.5
          <br />
          倍14天均量
        </span>
      ),
      dataIndex: 'volume_to_avg14_x2_percent',
      key: 'volume_breakout',
      width: getColumnWidth(110, 96),
      align: 'right',
      render: (value, record) => {
        const n = Number(value);
        if (!Number.isFinite(n) || n <= 0) {
          return <span style={{ color: '#999' }}>-</span>;
        }
        const color = record.volume_breakout ? '#ff4d4f' : '#000';
        return <span style={{ color }}>{`${n.toFixed(0)}%`}</span>;
      },
    },
    {
      title: '0.6腰斩线',
      dataIndex: 'waist_cut_06_line',
      key: 'waist_cut_06_line',
      width: getColumnWidth(100, 90),
      align: 'right',
      render: (value) => {
        if (value === undefined || value === null || value === 0) {
          return <span style={{ color: '#999' }}>-</span>;
        }
        return <span>{Number(value).toFixed(2)}</span>;
      },
    },
    {
      title: '监控跌破',
      dataIndex: 'monitor_drop_price',
      key: 'monitor_drop_price',
      width: getColumnWidth(100, 80),
      align: 'left',
      render: (value, record) => (
        <MonitorDropPriceEditor record={record} onSave={loadSubscribeStocks} />
      ),
    },
    {
      title: '监控涨过',
      dataIndex: 'monitor_rise_price',
      key: 'monitor_rise_price',
      width: getColumnWidth(100, 80),
      align: 'right',
      render: (value, record) => (
        <MonitorRisePriceEditor record={record} onSave={loadSubscribeStocks} />
      ),
    },
    {
      title: 'api卖出',
      dataIndex: 'sell_qty',
      key: 'sell_qty',
      width: getColumnWidth(90, 80),
      align: 'right',
      render: (value, record) => (
        <SellQtyEditor record={record} onSave={loadSubscribeStocks} />
      ),
    },
    {
      title: '市盈率',
      dataIndex: 'user_pe_ratio',
      key: 'user_pe_ratio',
      width: getColumnWidth(80, 70),
      align: 'right',
      render: (value) => formatPeRatio(value),
    },
    {
      title: '策略',
      dataIndex: 'high_sell',
      key: 'high_sell',
      width: getColumnWidth(90, 80),
      align: 'center',
      render: (_, record) => (
        <HighSellModeSwitch record={record} onSave={loadSubscribeStocks} />
      ),
    },
    {
      title: '1阶触发价',
      dataIndex: 'l1_trigger_price',
      key: 'l1_trigger_price',
      width: getColumnWidth(100, 85),
      align: 'right',
      render: (value) => {
        if (value === undefined || value === null || Number(value) <= 0) {
          return <span style={{ color: '#999' }}>-</span>;
        }
        return (
          <span style={{ fontWeight: 'bold' }}>
            {Number(value).toFixed(2)}
          </span>
        );
      },
    },
    {
      title: '最佳风险收益',
      key: 'recommended_option',
      width: getColumnWidth(220, 190),
      render: (_, record) => {
        if (!record.recommended_option) {
          return <span style={{ color: '#999' }}>无符合数据</span>;
        }
        const option = record.recommended_option;
        // 获取期权类型显示文本
        const optionTypeText = option.put_call === 'PUT' ? '看跌期权' : option.put_call === 'CALL' ? '看涨期权' : '期权';
        return (
          <div style={{ fontSize: needsScroll ? '12px' : '11px' }}>
            <div style={{ fontSize: '12px', color: '#666', marginBottom: '4px' }}>
              期权类型: {optionTypeText}
            </div>
            <div style={{ fontSize: '12px' }}>期权: {option.symbol || '-'}</div>
            <div style={{ fontSize: '11px', color: '#666' }}>
              行权价: {option.strike_price != null ? option.strike_price.toFixed(2) : '-'} | 
              到期日: {option.expiry_date || '-'}
            </div>
            {option.benefit !== undefined && option.benefit !== null && option.benefit > 0 && (
              <div style={{ fontSize: '11px', color: '#666' }}>
                价格: {option.benefit.toFixed(2)}
              </div>
            )}
            {option.profit_percent !== undefined && option.profit_percent !== null && (
              <div style={{ fontSize: '11px', color: '#34C759', fontWeight: 'bold', marginTop: '4px' }}>
                年化收益率: {option.profit_percent.toFixed(2)}%
              </div>
            )}
          </div>
        );
      },
    },
    {
      title: '看涨融资利率',
      key: 'call_funding_rate_option',
      width: getColumnWidth(120, 100),
      align: 'right',
      render: (_, record) => {
        if (!record.call_funding_rate_option) {
          return <span style={{ color: '#999' }}>暂无</span>;
        }
        const option = record.call_funding_rate_option;
        const mean3w = record.call_funding_rate_3w_mean;
        return (
          <div>
            {option.profit_percent !== undefined && option.profit_percent !== null ? (
              <div style={{ fontSize: '14px', color: '#52c41a', fontWeight: 'bold' }}>
                {option.profit_percent.toFixed(2)}%
              </div>
            ) : (
              <span style={{ color: '#999' }}>暂无数据</span>
            )}
            <div style={{ fontSize: '11px', color: '#888', marginTop: 2 }}>
              均值 {mean3w != null ? `${Number(mean3w).toFixed(2)}%` : '-'}
            </div>
          </div>
        );
      },
    },
    {
      title: '看跌融资利率',
      key: 'put_funding_rate_option',
      width: getColumnWidth(120, 100),
      align: 'right',
      render: (_, record) => {
        if (!record.put_funding_rate_option) {
          return <span style={{ color: '#999' }}>暂无</span>;
        }
        const option = record.put_funding_rate_option;
        const mean3w = record.put_funding_rate_3w_mean;
        return (
          <div>
            {option.profit_percent !== undefined && option.profit_percent !== null ? (
              <div style={{ fontSize: '14px', color: '#52c41a', fontWeight: 'bold' }}>
                {option.profit_percent.toFixed(2)}%
              </div>
            ) : (
              <span style={{ color: '#999' }}>暂无数据</span>
            )}
            <div style={{ fontSize: '11px', color: '#888', marginTop: 2 }}>
              均值 {mean3w != null ? `${Number(mean3w).toFixed(2)}%` : '-'}
            </div>
          </div>
        );
      },
    },
    {
      title: '操作',
      key: 'action',
      width: getColumnWidth(60, 50),
      align: 'center',
      render: (_, record) => (
        <Button
          type="link"
          onClick={() => handlePin(record.symbol)}
          title="置顶"
          style={{ padding: '4px 8px' }}
        >
          置顶
        </Button>
      ),
    },
  ];

  return (
    <div className="subscribe-stock-page equation-tab-page">
      <div className="subscribe-stock-card-shadow" style={{ marginBottom: 16 }}>
      <Card 
        className="subscribe-stock-card subscribe-stock-form-card"
        style={{ boxShadow: 'none' }}
        title={
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '8px' }}>
            <span>订阅股票管理</span>
            <div style={{ display: 'flex', alignItems: 'center', gap: '4px', flexWrap: 'wrap', justifyContent: 'flex-end' }}>
              <Button
                type="text"
                onClick={() => navigate('/pry-board')}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '4px',
                }}
              >
                撬板股票
                <RightOutlined />
              </Button>

              <Button
                type="text"
                onClick={() => navigate('/holding-management')}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '4px',
                }}
              >
                自动化交易
                <RightOutlined />
              </Button>
            </div>
          </div>
        }
        styles={{
          body: {
            padding: '12px'
          }
        }}
      >
        <Form
          form={form}
          layout="vertical"
        >
          <Form.Item>
            <Input.Group compact style={{ display: 'flex', alignItems: 'center' }}>
              <Select
                value={activePushType}
                onChange={setActivePushType}
                style={{ width: 200, marginRight: 8 }}
                options={[
                  { value: 'bark', label: '保存推送Key (Bark)' },
                  { value: 'pushdeer', label: '保存推送Key (PushDeer)' },
                ]}
              />
              <Input
                style={{ width: 'calc(100% - 260px)' }}
                placeholder={
                  activePushType === 'bark'
                    ? '请输入 Bark 推送 key（iOS 设备）'
                    : '请输入PushDeer推送key'
                }
                value={activePushType === 'bark' ? barkKey : pushKey}
                onChange={(e) => {
                  if (activePushType === 'bark') {
                    setBarkKey(e.target.value);
                  } else {
                    setPushKey(e.target.value);
                  }
                }}
              />
              <Button
                type="primary"
                icon={<SaveOutlined />}
                onClick={activePushType === 'bark' ? handleSaveBarkKey : handleSavePushKey}
                loading={activePushType === 'bark' ? loadingBarkKey : loadingPushKey}
                style={{ width: 80, marginLeft: 8 }}
              >
                保存
              </Button>
              <Tooltip
                title={
                  <img
                    src={activePushType === 'bark' ? getBarkImagePath() : getImagePath()}
                    alt={activePushType === 'bark' ? 'Bark 说明' : 'PushDeer二维码'}
                    style={{
                      maxWidth: '300px',
                      display: 'block',
                      border: 'none',
                      outline: 'none',
                      padding: 0,
                      margin: 0,
                    }}
                    onError={(e) => {
                      if (e.target.src.includes('/equation')) {
                        e.target.src =
                          activePushType === 'bark'
                            ? '/equation/images/bark-app-qrcode.png'
                            : '/equation/images/pushdeer-qrcode.png';
                      } else {
                        e.target.src =
                          activePushType === 'bark'
                            ? '/images/bark-app-qrcode.png'
                            : '/images/pushdeer-qrcode.png';
                      }
                    }}
                  />
                }
                placement="topRight"
                overlayInnerStyle={{ padding: 0 }}
              >
                <QuestionCircleOutlined
                  style={{
                    marginLeft: '8px',
                    fontSize: '16px',
                    color: '#007AFF',
                    cursor: 'pointer',
                  }}
                />
              </Tooltip>
            </Input.Group>
          </Form.Item>
          <AutoComplete
            options={options}
            onSearch={handleSearch}
            onSelect={handleSelect}
            placeholder="请输入股票代码或名称，来添加股票"
            loading={loading}
            style={{ 
              width: '100%',
              marginBottom: '16px'
            }}
          />

          {selectedStocks.length > 0 && (
            <Table
              dataSource={selectedStocks}
              columns={[
                {
                  title: '股票名称',
                  dataIndex: 'chinese_name',
                  key: 'chinese_name',
                  ellipsis: true,
                },
                {
                  title: '股票符号',
                  dataIndex: 'symbol',
                  key: 'symbol',
                  ellipsis: true,
                },
                {
                  title: '监控跌破',
                  key: 'monitor_drop_price',
                  width: 120,
                  render: (_, record) => (
                    <Input
                      type="number"
                      placeholder="监控跌破（可选）"
                      value={record.monitor_drop_price || ''}
                      onChange={(e) => {
                        const price = parseFloat(e.target.value) || 0;
                        handleUpdateMonitorDropPrice(record.symbol, price);
                      }}
                      step="0.01"
                      min="0"
                      style={{ width: '100%' }}
                    />
                  ),
                },
                {
                  title: '监控涨过',
                  key: 'monitor_rise_price',
                  width: 120,
                  render: (_, record) => (
                    <Input
                      type="number"
                      placeholder="监控涨过（可选）"
                      value={record.monitor_rise_price || ''}
                      onChange={(e) => {
                        const price = parseFloat(e.target.value) || 0;
                        handleUpdateMonitorRisePrice(record.symbol, price);
                      }}
                      step="0.01"
                      min="0"
                      style={{ width: '100%' }}
                    />
                  ),
                },
                {
                  title: 'api卖出',
                  key: 'sell_qty',
                  width: 100,
                  render: (_, record) => (
                    <Input
                      type="number"
                      placeholder="0"
                      value={record.sell_qty > 0 ? record.sell_qty : ''}
                      onChange={(e) => {
                        const qty = parseInt(e.target.value, 10);
                        setSelectedStocks((stocks) =>
                          stocks.map((s) =>
                            s.symbol === record.symbol
                              ? { ...s, sell_qty: Number.isNaN(qty) ? 0 : Math.max(0, qty) }
                              : s
                          )
                        );
                      }}
                      step="1"
                      min="0"
                      style={{ width: '100%' }}
                    />
                  ),
                },
                {
                  title: '操作',
                  key: 'action',
                  width: 60,
                  render: (_, record) => (
                    <Button 
                      type="link" 
                      danger 
                      onClick={() => handleRemoveStock(record.symbol)}
                      style={{
                        padding: '4px 8px'
                      }}
                    >
                      删除
                    </Button>
                  ),
                },
              ]}
              rowKey="symbol"
              pagination={false}
              size="small"
              scroll={{ x: 'max-content' }}
              style={{
                marginBottom: '16px'
              }}
            />
          )}

          <Button 
            type="primary"
            icon={<PlusOutlined />}
            onClick={handleAdd}
            disabled={selectedStocks.length === 0}
            style={{
              width: '100%',
              height: '40px',
              fontSize: '16px',
            }}
          >
            添加
          </Button>
        </Form>
      </Card>
      </div>

      <div className="subscribe-stock-card-shadow">
      <Card 
        className="subscribe-stock-card subscribe-stock-table-card"
        style={{ boxShadow: 'none' }}
        title="订阅股票列表" 
        styles={{
          body: {
            padding: '12px',
            overflowX: needsScroll ? 'auto' : 'visible'
          }
        }}
        extra={
          <Button 
            type="primary"
            danger
            icon={<DeleteOutlined />}
            onClick={handleDelete}
            disabled={selectedRowKeys.length === 0}
            size="small"
          >
            删除选中
          </Button>
        }
      >
        <Table
          className="subscribe-stock-table"
          columns={subscribeColumns}
          dataSource={subscribeStocks}
          rowKey="symbol"
          loading={loadingStocks}
          size="small"
          scroll={needsScroll ? { x: 'max-content' } : undefined}
          rowSelection={{
            selectedRowKeys,
            onChange: setSelectedRowKeys,
          }}
          pagination={{
            current: listPage,
            pageSize: SUBSCRIBE_STOCKS_PAGE_SIZE,
            total: listTotal,
            showSizeChanger: false,
            showQuickJumper: true,
            showTotal: (total) => `共 ${total} 条`,
            onChange: (page) => loadSubscribeStocks(page),
          }}
        />
      </Card>
      </div>
    </div>
  );
}

export default SubscribeStock;
