import { cbondFirstDayMeta } from './cbondFirstDayData';
import request from '../utils/request';

const mergeCbondRows = (baseRows, updateRows) => {
  const rowMap = new Map(baseRows.map((row) => [row.code, row]));
  updateRows.forEach((row) => {
    rowMap.set(row.code, row);
  });
  return Array.from(rowMap.values()).sort((left, right) => right.listDate.localeCompare(left.listDate));
};

const maxListDate = (rows, fallback) =>
  rows.reduce((max, row) => (row.listDate > max ? row.listDate : max), fallback);

/** 从后端增量拉取 since 之后新上市可转债首日数据，并与现有快照合并 */
export const fetchCbondFirstDayUpdates = async (baseRows = [], since = cbondFirstDayMeta.rangeEnd) => {
  const sinceParam = maxListDate(baseRows, since);
  const response = await request(
    `/api/new-stock/cbond-first-day-updates?since=${encodeURIComponent(sinceParam)}`,
    { method: 'GET' }
  );

  const payload = response?.data;
  if (!payload) {
    throw new Error('cbond updates payload invalid');
  }

  const updateRows = Array.isArray(payload.rows) ? payload.rows : [];
  const mergedRows = mergeCbondRows(baseRows, updateRows);

  return {
    rows: mergedRows,
    since: sinceParam,
    rangeStart: cbondFirstDayMeta.rangeStart,
    rangeEnd: maxListDate(mergedRows, cbondFirstDayMeta.rangeEnd),
    source: payload.source || cbondFirstDayMeta.source,
    message:
      updateRows.length > 0
        ? payload.message || `已合并 ${updateRows.length} 只新上市可转债。`
        : payload.message || `暂无 ${sinceParam} 之后的新上市可转债，当前样本已是最新。`,
    fetchedAt: payload.fetchedAt || cbondFirstDayMeta.snapshotLabel,
    updateCount: updateRows.length,
    totalFound: payload.totalFound ?? updateRows.length,
  };
};

/** 拉取待上市可转债日历（上市日由近到远） */
export const fetchCbondUpcomingCalendar = async () => {
  const response = await request('/api/new-stock/cbond-upcoming-calendar', { method: 'GET' });
  const payload = response?.data;
  if (!payload) {
    throw new Error('cbond upcoming payload invalid');
  }

  const rows = Array.isArray(payload.rows)
    ? [...payload.rows].sort((left, right) => left.listDate.localeCompare(right.listDate))
    : [];

  return {
    rows,
    source: payload.source || cbondFirstDayMeta.source,
    message: payload.message || (rows.length > 0 ? `共 ${rows.length} 只待上市可转债。` : '近期暂无待上市可转债。'),
    fetchedAt: payload.fetchedAt || cbondFirstDayMeta.snapshotLabel,
  };
};
