import React from 'react';
import { Navigate, useNavigate, useParams } from 'react-router-dom';
import { ArrowLeftOutlined, RightOutlined } from '@ant-design/icons';
import { hefeiVcCompanies } from '../data/hefeiVcCompanies';
import FundMarkdownPage from './FundMarkdownPage';

const LIST_PATH = '/fund-temperature/hefei-vc';

function HefeiVcCompanyList() {
  const navigate = useNavigate();

  return (
    <div className="equation-fund-temperature-page equation-tab-page" style={{ background: '#F2F2F7' }}>
      <div className="equation-fund-landing-inner">
        <div
          className="equation-page-header"
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 12,
            marginBottom: 8,
          }}
        >
          <ArrowLeftOutlined
            style={{ fontSize: 20, color: '#1C1C1E', cursor: 'pointer' }}
            onClick={() => navigate('/fund-temperature')}
          />
          <span style={{ fontSize: 22, fontWeight: 700, color: '#1C1C1E' }}>企业家故事会</span>
        </div>
        <p className="equation-fund-landing-subtitle" style={{ marginBottom: 16 }}>
          收录公开报道中合肥国资创投体系（建投 / 产投 / 兴泰等）的代表性投资企业；点击进入企业家故事。内容整理自公开资料，不构成投资建议。
        </p>
        <div className="equation-fund-landing-grid">
          {hefeiVcCompanies.map((item) => (
            <button
              key={item.slug}
              type="button"
              className="equation-fund-entry-card"
              onClick={() => navigate(`${LIST_PATH}/${item.slug}`)}
            >
              <span className="equation-fund-entry-text" style={{ flex: 1 }}>
                <span className="equation-fund-entry-name">{item.name}</span>
                <span className="equation-fund-entry-desc">
                  {item.sector} · {item.founder}
                  <br />
                  {item.desc}
                </span>
              </span>
              <RightOutlined style={{ fontSize: 16, color: '#AEAEB2', flexShrink: 0 }} />
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

/** 复用 FundMarkdownPage 展示创始人故事 */
function HefeiVcCompanyStory() {
  const { slug } = useParams();
  const company = hefeiVcCompanies.find((item) => item.slug === slug);
  if (!company) {
    return <Navigate to={LIST_PATH} replace />;
  }
  return (
    <FundMarkdownPage
      title={`${company.name} · 企业家故事`}
      fileName={company.storyFile}
      backTo={LIST_PATH}
    />
  );
}

export { HefeiVcCompanyList, HefeiVcCompanyStory };
