import React, { useState, useEffect } from 'react';
import { Card, Row, Col, Input, Button, message } from 'antd';
import { RightOutlined, EditOutlined, SaveOutlined, LogoutOutlined } from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import request from '../utils/request';

const { TextArea } = Input;

function RiskControl() {
  const navigate = useNavigate();
  const [messages, setMessages] = useState([]);
  const [editingIndex, setEditingIndex] = useState(null);
  const [editText, setEditText] = useState('');
  const [saving, setSaving] = useState(false);

  // 默认值
  const defaultMessages = [
    '贝莱德近十个月港美股，及中国大陆持仓变更',
    '摩根大通公司近十个月港股和A股主要持仓变更',
    '中财期货公司近十个月主要持仓变更',
    '',
    '',
    '',
  ];

  // 加载消息项
  useEffect(() => {
    loadMessages();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const loadMessages = async () => {
    try {
      const response = await request('/api/risk-control/holding-change-messages');
      if (response.code === 200 && Array.isArray(response.data)) {
        // 确保有6个消息项
        const msgs = [...response.data];
        while (msgs.length < 6) {
          msgs.push({
            index: msgs.length,
            text: defaultMessages[msgs.length] || '',
          });
        }
        setMessages(msgs);
      } else {
        // 如果API失败，使用默认值
        const msgs = defaultMessages.map((text, index) => ({
          index,
          text,
        }));
        setMessages(msgs);
      }
    } catch (error) {
      console.error('加载消息项失败:', error);
      // 使用默认值
      const msgs = defaultMessages.map((text, index) => ({
        index,
        text,
      }));
      setMessages(msgs);
    }
  };

  const handleEdit = (index) => {
    setEditingIndex(index);
    setEditText(messages[index]?.text || '');
  };

  const handleSave = async (index) => {
    const newMessages = [...messages];
    newMessages[index] = {
      index,
      text: editText.trim(),
    };
    setMessages(newMessages);
    setEditingIndex(null);
    setEditText('');

    // 保存到后端
    try {
      setSaving(true);
      const response = await request('/api/risk-control/holding-change-messages', {
        method: 'POST',
        body: JSON.stringify({
          messages: newMessages,
        }),
      });
      if (response.code === 200) {
        message.success('保存成功');
      } else {
        message.error(response.message || '保存失败');
        // 恢复原值
        loadMessages();
      }
    } catch (error) {
      console.error('保存消息项失败:', error);
      message.error('保存失败，请稍后重试');
      // 恢复原值
      loadMessages();
    } finally {
      setSaving(false);
    }
  };

  const handleCancel = () => {
    setEditingIndex(null);
    setEditText('');
  };

  const handleMessageClick = (message) => {
    // 获取显示的文案（如果为空，使用默认值）
    const displayText = message.text || defaultMessages[message.index] || '';
    // 跳转到详情页面，传递entity和keyword参数
    navigate(`/holding-change-detail?entity=${encodeURIComponent(displayText)}&keyword=${encodeURIComponent(displayText)}`);
  };

  const handleMathProofClick = () => {
    navigate('/math-proof');
  };

  const handleDonationClick = () => {
    navigate('/more');
  };

  const handleLowBuyStrategyClick = () => {
    navigate('/option-calculator/low-buy');
  };

  const handleHighSellStrategyClick = () => {
    const token = localStorage.getItem('token');
    if (!token) {
      message.error('请先登录');
      window.location.hash = '#/login';
      return;
    }
    navigate('/option-calculator/high-sell');
  };

  const handleLogout = async () => {
    try {
      await request('/api/auth/logout', { method: 'POST' });
    } catch (e) {
      // 忽略错误，仍清除本地并跳转
    }
    localStorage.removeItem('token');
    window.location.hash = '#/login';
  };

  const getDisplayText = (message) => {
    if (message.text && message.text.trim()) {
      return message.text;
    }
    const defaultText = defaultMessages[message.index];
    if (defaultText && defaultText.trim()) {
      return defaultText;
    }
    return '请输入关注话题';
  };

  return (
    <div className="equation-tab-page">
      {/* 捐赠信息模块 */}
      <Card 
        title="捐赠信息"
        style={{ 
          margin: '16px',
          marginBottom: 24,
          borderRadius: '14px',
          boxShadow: '0 2px 8px rgba(0,0,0,0.06)',
          overflow: 'hidden'
        }}
        bodyStyle={{ padding: '12px' }}
      >
        <Row gutter={[12, 12]}>
          <Col span={24}>
            <Card
              size="small"
              hoverable
              onClick={handleDonationClick}
              style={{
                cursor: 'pointer',
                borderRadius: '12px',
                transition: 'all 0.2s ease',
              }}
              bodyStyle={{ padding: '12px' }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span style={{ 
                  fontSize: '15px', 
                  color: '#1C1C1E'
                }}>按月捐赠作者</span>
                <RightOutlined style={{ 
                  fontSize: '16px', 
                  color: '#AEAEB2',
                  flexShrink: 0
                }} />
              </div>
            </Card>
          </Col>
        </Row>
      </Card>

      {/* 期权计算器 */}
      <Card
        title="期权计算器"
        style={{
          margin: '16px',
          marginBottom: 24,
          borderRadius: '8px',
          overflow: 'hidden',
        }}
        bodyStyle={{ padding: '12px' }}
      >
        <Row gutter={[12, 12]}>
          <Col span={24}>
            <Card
              size="small"
              hoverable
              onClick={handleLowBuyStrategyClick}
              style={{
                cursor: 'pointer',
                borderRadius: '12px',
                transition: 'all 0.2s ease',
              }}
              bodyStyle={{ padding: '12px' }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span style={{ fontSize: '15px', color: '#1C1C1E' }}>低买策略</span>
                <RightOutlined style={{ fontSize: '16px', color: '#AEAEB2', flexShrink: 0 }} />
              </div>
            </Card>
          </Col>
          <Col span={24}>
            <Card
              size="small"
              hoverable
              onClick={handleHighSellStrategyClick}
              style={{
                cursor: 'pointer',
                borderRadius: '12px',
                transition: 'all 0.2s ease',
              }}
              bodyStyle={{ padding: '12px' }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span style={{ fontSize: '15px', color: '#1C1C1E' }}>高卖策略</span>
                <RightOutlined style={{ fontSize: '16px', color: '#AEAEB2', flexShrink: 0 }} />
              </div>
            </Card>
          </Col>
        </Row>
      </Card>

      {/* 关注资讯--自定义主题（原持仓变更消息列表） */}
      <Card
        title="关注资讯--自定义主题"
        style={{ 
          margin: '16px',
          marginBottom: 24,
          borderRadius: '14px',
          boxShadow: '0 2px 8px rgba(0,0,0,0.06)',
          overflow: 'hidden'
        }}
        bodyStyle={{ padding: '12px' }}
      >
        <Row gutter={[12, 12]}>
          {messages.map((message, index) => (
            <Col span={24} key={index}>
              <Card
                size="small"
                style={{
                  borderRadius: '6px',
                  transition: 'all 0.3s',
                }}
                bodyStyle={{ padding: '12px' }}
              >
                {editingIndex === index ? (
                  <div>
                    <TextArea
                      value={editText}
                      onChange={(e) => setEditText(e.target.value)}
                      rows={2}
                      placeholder={defaultMessages[index] || '请输入关注话题'}
                      style={{ marginBottom: '8px' }}
                    />
                    <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '8px' }}>
                      <Button
                        size="small"
                        onClick={handleCancel}
                      >
                        取消
                      </Button>
                      <Button
                        type="primary"
                        size="small"
                        icon={<SaveOutlined />}
                        onClick={() => handleSave(index)}
                        loading={saving}
                      >
                        保存
                      </Button>
                    </div>
                  </div>
                ) : (
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div style={{ flex: 1, cursor: 'pointer' }} onClick={() => handleMessageClick(message)}>
                      <span style={{ 
                        fontSize: '15px', 
                        color: '#1C1C1E'
                      }}>{getDisplayText(message)}</span>
                    </div>
                    <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                      <Button
                        type="text"
                        size="small"
                        icon={<EditOutlined />}
                        onClick={() => handleEdit(index)}
                        style={{ padding: '0 4px' }}
                      />
                      <RightOutlined 
                        style={{ 
                          fontSize: '16px', 
                          color: '#AEAEB2',
                          flexShrink: 0,
                          cursor: 'pointer'
                        }}
                        onClick={() => handleMessageClick(message)}
                      />
                    </div>
                  </div>
                )}
                </Card>
              </Col>
            ))}
          </Row>
      </Card>

      {/* 数学推导模块 */}
      <Card
        title="数学推导"
        style={{
          margin: '16px',
          marginBottom: 24,
          borderRadius: '8px',
          overflow: 'hidden',
        }}
        bodyStyle={{ padding: '12px' }}
      >
        <Row gutter={[12, 12]}>
          <Col span={24}>
            <Card
              size="small"
              hoverable
              onClick={handleMathProofClick}
              style={{
                cursor: 'pointer',
                borderRadius: '12px',
                transition: 'all 0.2s ease',
              }}
              bodyStyle={{ padding: '12px' }}
            >
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span style={{ fontSize: '15px', color: '#1C1C1E' }}>期权备兑策略的盈利性证明</span>
                <RightOutlined style={{ fontSize: '16px', color: '#AEAEB2', flexShrink: 0 }} />
              </div>
            </Card>
          </Col>
        </Row>
      </Card>

      {/* 退出登录 */}
      <Card
        style={{
          margin: '16px',
          marginBottom: 24,
          borderRadius: '8px',
          overflow: 'hidden',
        }}
        bodyStyle={{ padding: '12px' }}
      >
        <Button
          type="default"
          danger
          block
          icon={<LogoutOutlined />}
          onClick={handleLogout}
        >
          退出登录
        </Button>
      </Card>
    </div>
  );
}

export default RiskControl; 
